                <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-coral-burst"></div>
              </div>
            ) : shareLink ? (
              <>
                {/* Tabs */}
                <div className="flex gap-1 p-1 bg-gray-100 dark:bg-gray-800 rounded-xl">
