interface DeleteConfirmModalProps {
  isOpen: boolean;
  onClose: () => void;
  onConfirm: () => void;
  count: number;
  isDeleting: boolean;
}

export const DeleteConfirmModal: React.FC<DeleteConfirmModalProps> = ({
  isOpen,
  onClose,
  onConfirm,
  count,
  isDeleting,
}) => {
  if (!isOpen) return null;

  return (
    <AnimatePresence>
      <motion.div
        className="fixed inset-0 z-200 flex items-center justify-center p-4"
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        exit={{ opacity: 0 }}
      >
        <motion.div className="absolute inset-0 bg-black/60 backdrop-blur-sm" onClick={onClose} />

        <motion.div
          className="relative bg-white rounded-2xl border-2 border-peach-soft w-full max-w-sm overflow-hidden"
          initial={{ scale: 0.9, opacity: 0 }}
          animate={{ scale: 1, opacity: 1 }}
          exit={{ scale: 0.9, opacity: 0 }}
        >
          <div className="p-6 text-center">
            <div className="w-16 h-16 bg-red-100 rounded-full flex items-center justify-center mx-auto mb-4">
              <AlertTriangle className="w-8 h-8 text-red-500" />
            </div>

            <h3 className="text-xl font-bold text-charcoal-soft mb-2">
              Delete {count} Book{count > 1 ? 's' : ''}?
            </h3>

            <p className="text-cocoa-light mb-6">
              This action cannot be undone. All selected books and their illustrations will be
              permanently deleted.
            </p>

            <div className="flex gap-3">
              <Button
                variant="outline"
                onClick={onClose}
                disabled={isDeleting}
                className="flex-1 py-3"
              >
                Cancel
              </Button>
              <Button
                variant="destructive"
                onClick={onConfirm}
                disabled={isDeleting}
                className="flex-1 py-3 flex"
              >
                {isDeleting ? (
                  <>
                    <motion.div
                      animate={{ rotate: 360 }}
                      transition={{ repeat: Number.POSITIVE_INFINITY, duration: 1 }}
                    >
                      <Trash2 className="w-4 h-4" />
                    </motion.div>
                    Deleting...
                  </>
                ) : (
                  <>
                    <Trash2 className="w-4 h-4" />
                    Delete
                  </>
                )}
              </Button>
            </div>
          </div>
        </motion.div>
      </motion.div>
    </AnimatePresence>
  );
};

// Selectable Book Card wrapper
interface SelectableCardProps {
  children: React.ReactNode;
  isSelectionMode: boolean;
  isSelected: boolean;
  onSelect: () => void;
  onLongPress?: () => void;
}

export const SelectableCard: React.FC<SelectableCardProps> = ({
  children,
  isSelectionMode,
  isSelected,
  onSelect,
  onLongPress,
}) => {
  const [pressTimer, setPressTimer] = useState<NodeJS.Timeout | null>(null);

  const handleTouchStart = () => {
    if (!isSelectionMode && onLongPress) {
      const timer = setTimeout(() => {
        onLongPress();
        onSelect();
      }, 500);
      setPressTimer(timer);
    }
  };

  const handleTouchEnd = () => {
    if (pressTimer) {
      clearTimeout(pressTimer);
      setPressTimer(null);
    }
  };

  return (
    <div
      className={`
                relative transition-all duration-200
                ${isSelectionMode ? 'cursor-pointer' : ''}
                ${isSelected ? 'ring-2 ring-coral-burst ring-offset-2 rounded-2xl' : ''}
            `}
      onClick={isSelectionMode ? onSelect : undefined}
      onTouchStart={handleTouchStart}
      onTouchEnd={handleTouchEnd}
      onTouchCancel={handleTouchEnd}
    >
      {/* Selection checkbox */}
      <AnimatePresence>
        {isSelectionMode && (
          <motion.div
            initial={{ scale: 0, opacity: 0 }}
            animate={{ scale: 1, opacity: 1 }}
            exit={{ scale: 0, opacity: 0 }}
            className="absolute top-3 left-3 z-10"
          >
            <div
              className={`
                            w-6 h-6 rounded-full flex items-center justify-center
                            transition-colors
                            ${
                              isSelected
                                ? 'bg-coral-burst text-white'
                                : 'bg-white border-2 border-peach-soft'
                            }
                        `}
            >
              {isSelected && <Check className="w-4 h-4" />}
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Overlay when selected */}
      {isSelected && (
        <div className="absolute inset-0 bg-coral-burst/10 rounded-2xl pointer-events-none" />
      )}

      {children}
    </div>
  );
};

