import { ArrowRight, Loader2, Mail, Sparkles } from 'lucide-react';
import type React from 'react';
import { useState } from 'react';
import { useAuth } from '../contexts/AuthContext';
import { supabase } from '../services/supabaseClient';
import { Button } from './ui/button';
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle } from './ui/dialog';
import { Input } from './ui/input';
import { Separator } from './ui/separator';

interface EmailAuthModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSuccess?: () => void;
}

const EmailAuthModal: React.FC<EmailAuthModalProps> = ({ isOpen, onClose, onSuccess }) => {
  const { signInWithEmail } = useAuth();
  const [email, setEmail] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [successMessage, setSuccessMessage] = useState<string | null>(null);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);
    setSuccessMessage(null);
    setIsLoading(true);

    try {
      const { error } = await supabase.auth.signInWithOtp({
        email,
        options: {
          data: { display_name: email.split('@')[0] },
          emailRedirectTo: window.location.origin,
        },
      });

      if (error) throw error;

      setSuccessMessage('Magic link sent! Check your email to sign in. Γ£¿');

      try {
        const existingSettings = JSON.parse(localStorage.getItem('genesis_settings') || '{}');
        localStorage.setItem(
          'genesis_settings',
          JSON.stringify({ ...existingSettings, email })
        );
      } catch (e) {
        console.error('Failed to save settings:', e);
      }
    } catch (err: any) {
      console.error('[EmailAuth] Error:', err);
      let errorMessage =
        err.message || err.error_description || 'Something went wrong. Please try again.';

      if (errorMessage === '{}' || (typeof err === 'object' && Object.keys(err).length === 0)) {
        errorMessage = 'Unable to send link. Please check your network or try again later.';
      }

      if (errorMessage.includes('Rate limit') || err.status === 429) {
        errorMessage = 'Too many attempts. Please wait a moment before trying again.';
      }

      setError(errorMessage);
    } finally {
      setIsLoading(false);
    }
  };

  const handleGoogleSignIn = async () => {
    setError(null);
    setIsLoading(true);

    try {
      onClose();

      const { data, error } = await supabase.auth.signInWithOAuth({
        provider: 'google',
        options: {
          redirectTo: window.location.origin,
          queryParams: { access_type: 'offline', prompt: 'consent' },
        },
      });

      if (error) throw error;
    } catch (err: any) {
      console.error('[EmailAuth] Google error:', err);
      setError(err.message || 'Failed to sign in with Google.');
      setIsLoading(false);
    }
  };

  return (
    <Dialog open={isOpen} onOpenChange={(open) => { if (!open) onClose(); }}>
      <DialogContent className="max-w-sm p-0 overflow-hidden">
        {/* Header */}
        <DialogHeader className="pt-8 px-6 pb-2 text-center">
          <div className="w-12 h-12 rounded-xl bg-linear-to-br from-gold-sunshine to-coral-burst mx-auto mb-4 flex items-center justify-center transform rotate-3">
            <Sparkles className="w-6 h-6 text-white" />
          </div>
          <DialogTitle className="text-2xl text-center">Welcome to Genesis</DialogTitle>
          <DialogDescription className="text-center">
            Your journey to magical storytelling begins here.
          </DialogDescription>
        </DialogHeader>

        {/* Content */}
        <div className="px-6 pb-6 space-y-5">
          {/* Error/Success Messages */}
          {error && (
            <div className="p-3 bg-red-50 text-red-600 text-xs font-bold rounded-xl text-center border-2 border-red-100 animate-in fade-in-0 slide-in-from-top-1 duration-200">
              {error}
            </div>
          )}
          {successMessage && (
            <div className="p-3 bg-green-50 text-green-600 text-xs font-bold rounded-xl text-center border-2 border-green-100 animate-in fade-in-0 slide-in-from-top-1 duration-200">
              {successMessage}
            </div>
          )}

          {/* Magic Link Form */}
          <form onSubmit={handleSubmit} className="space-y-4">
            <div className="relative group">
              <Mail className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-cocoa-light group-focus-within:text-coral-burst transition-colors" />
              <Input
                type="email"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                placeholder="Enter your email"
                required
                className="pl-12 h-12 rounded-2xl"
              />
            </div>

            <Button
              type="submit"
              disabled={isLoading || !email}
              className="w-full h-12 rounded-2xl"
            >
              {isLoading ? (
                <Loader2 className="w-5 h-5 animate-spin" />
              ) : (
                <>
                  Send Magic Link <ArrowRight className="w-4 h-4" />
                </>
              )}
            </Button>
          </form>

          {/* Divider */}
          <div className="relative flex items-center py-1">
            <Separator className="flex-1" />
            <span className="shrink-0 mx-4 text-xs font-heading font-bold text-cocoa-light uppercase tracking-wider">
              Or
            </span>
            <Separator className="flex-1" />
          </div>

          {/* Google Sign In */}
          <Button
            variant="outline"
            onClick={handleGoogleSignIn}
            disabled={isLoading}
            className="w-full h-12 rounded-2xl gap-3 group"
          >
            <svg
              className="w-5 h-5 group-hover:scale-110 transition-transform"
              viewBox="0 0 24 24"
            >
              <path fill="#4285F4" d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92c-.26 1.37-1.04 2.53-2.21 3.31v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.09z" />
              <path fill="#34A853" d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z" />
              <path fill="#FBBC05" d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.07H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.93l2.85-2.22.81-.62z" />
              <path fill="#EA4335" d="M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.07l3.66 2.84c.87-2.6 3.3-4.53 6.16-4.53z" />
            </svg>
            Continue with Google
          </Button>
        </div>
      </DialogContent>
    </Dialog>
  );
};

export default EmailAuthModal;

// ==============================================================================
// ERROR BOUNDARY COMPONENT
// ==============================================================================
// Catches JavaScript errors anywhere in the child component tree
// and displays a fallback UI instead of crashing the whole app
// Platform-grade error handling with recovery and reporting
// ==============================================================================

import { AlertTriangle, Bug, Check, Copy, Home, RefreshCw } from 'lucide-react';
import type React from 'react';
import { Component, type ErrorInfo, type ReactNode } from 'react';
import { Button } from './ui/button';

// Dynamic import to avoid circular dependencies
const reportError = async (
  error: Error,
  errorInfo: ErrorInfo,
  context: Record<string, unknown>
) => {
  try {
    const { errorReporter } = await import('../services/errorReporting');
    errorReporter.captureException(error, {
      component: 'ErrorBoundary',
      metadata: {
        componentStack: errorInfo.componentStack,
        ...context,
      },
    });
  } catch {
    // Fallback to console if error reporter fails
    console.error('[ErrorBoundary] Failed to report error:', error);
  }
};

interface Props {
  children: ReactNode;
  fallback?: ReactNode;
  onError?: (error: Error, errorInfo: ErrorInfo) => void;
  /** Component name for error context */
  componentName?: string;
  /** Retry limit before showing persistent error */
  maxRetries?: number;
  /** Show detailed error info even in production */
  showDetails?: boolean;
}

interface State {
  hasError: boolean;
  error: Error | null;
  errorInfo: ErrorInfo | null;
  retryCount: number;
  errorId: string | null;
  copied: boolean;
}

class ErrorBoundary extends Component<Props, State> {
  public state: State = {
    hasError: false,
    error: null,
    errorInfo: null,
    retryCount: 0,
    errorId: null,
    copied: false,
  };

  public static getDerivedStateFromError(error: Error): Partial<State> {
    // Generate unique error ID for tracking
    const errorId =
      `ERR-${Date.now().toString(36)}-${Math.random().toString(36).substr(2, 5)}`.toUpperCase();
    return { hasError: true, error, errorId };
  }

  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {
    this.setState({ errorInfo });

    const { componentName, maxRetries = 3 } = this.props;

    // Report to error tracking service
    reportError(error, errorInfo, {
      errorId: this.state.errorId,
      componentName,
      retryCount: this.state.retryCount,
      url: typeof window !== 'undefined' ? window.location.href : undefined,
    });

    // Call optional onError callback
    this.props.onError?.(error, errorInfo);

    // Log for debugging
    console.error('[ErrorBoundary] Caught error:', {
      errorId: this.state.errorId,
      error,
      componentStack: errorInfo.componentStack,
      retryCount: this.state.retryCount,
      maxRetries,
    });
  }

  private handleRetry = (): void => {
    const { maxRetries = 3 } = this.props;
    const newRetryCount = this.state.retryCount + 1;

    if (newRetryCount >= maxRetries) {
      // Max retries reached, show persistent error
      console.warn(`[ErrorBoundary] Max retries (${maxRetries}) reached`);
      return;
    }

    this.setState({
      hasError: false,
      error: null,
      errorInfo: null,
      retryCount: newRetryCount,
      copied: false,
    });
  };

  private handleGoHome = (): void => {
    window.location.href = '/';
  };

  private handleRefresh = (): void => {
    window.location.reload();
  };

  private handleCopyError = (): void => {
    const errorText = this.getErrorReport();
    navigator.clipboard.writeText(errorText).then(() => {
      this.setState({ copied: true });
      setTimeout(() => this.setState({ copied: false }), 2000);
    }).catch(() => {
      // Clipboard API unavailable (insecure context or permission denied)
      console.warn('Failed to copy error report to clipboard');
    });
  };

  private getErrorReport = (): string => {
    const { error, errorInfo, errorId } = this.state;
    return [
      `Error ID: ${errorId}`,
      `Time: ${new Date().toISOString()}`,
      `URL: ${typeof window !== 'undefined' ? window.location.href : 'N/A'}`,
      `User Agent: ${typeof navigator !== 'undefined' ? navigator.userAgent : 'N/A'}`,
      '',
      `Error: ${error?.name}: ${error?.message}`,
      '',
      'Stack Trace:',
      error?.stack || 'No stack trace',
      '',
      'Component Stack:',
      errorInfo?.componentStack || 'No component stack',
    ].join('\n');
  };

  private canRetry = (): boolean => {
    const { maxRetries = 3 } = this.props;
    return this.state.retryCount < maxRetries;
  };

  public render(): ReactNode {
    if (this.state.hasError) {
      // Custom fallback UI if provided
      if (this.props.fallback) {
        return this.props.fallback;
      }

      const { showDetails } = this.props;
      const { errorId, error, errorInfo, retryCount, copied } = this.state;
      const canRetry = this.canRetry();
      const showErrorDetails = import.meta.env.DEV || showDetails;

      // Default error UI
      return (
        <div className="min-h-screen flex items-center justify-center bg-linear-to-br from-cream-base to-peach-soft p-4">
            <div className="bg-white rounded-3xl border-2 border-peach-soft p-8 max-w-lg w-full text-center">
            <div className="w-16 h-16 mx-auto mb-6 bg-red-100 rounded-full flex items-center justify-center">
              <AlertTriangle className="w-8 h-8 text-red-500" />
            </div>

            <h1 className="font-heading font-bold text-2xl text-charcoal-soft mb-3">
              Oops! Something went wrong
            </h1>

            <p className="text-cocoa-light mb-4">
              We're sorry, but something unexpected happened. Don't worry, your work is safe!
            </p>

            {/* Error ID for support */}
            <div className="mb-6 px-4 py-2 bg-gray-50 rounded-lg inline-block">
              <span className="text-xs text-gray-500">Error ID: </span>
              <code className="text-xs font-mono text-gray-700">{errorId}</code>
            </div>

            {/* Error details */}
            {showErrorDetails && error && (
              <details className="mb-6 text-left bg-gray-50 rounded-xl p-4">
                <summary className="cursor-pointer text-sm font-bold text-gray-600 mb-2 flex items-center gap-2">
                  <Bug className="w-4 h-4" />
                  Error Details {import.meta.env.DEV && '(Dev Mode)'}
                </summary>
                <pre className="text-xs text-red-600 overflow-auto max-h-40 whitespace-pre-wrap">
                  {error.toString()}
                  {errorInfo?.componentStack}
                </pre>
                <Button
                  variant="ghost"
                  size="sm"
                  onClick={this.handleCopyError}
                  className="mt-3 text-gray-500 hover:text-gray-700 flex gap-1"
                >
                  {copied ? <Check className="w-3 h-3" /> : <Copy className="w-3 h-3" />}
                  {copied ? 'Copied!' : 'Copy error report'}
                </Button>
              </details>
            )}

            {/* Retry count indicator */}
            {retryCount > 0 && (
              <p className="text-xs text-amber-600 mb-4">
                Retry attempt {retryCount}/{this.props.maxRetries || 3}
              </p>
            )}

            <div className="flex flex-col sm:flex-row gap-3 justify-center">
              {canRetry ? (
                <Button
                  variant="primary"
                  onClick={this.handleRetry}
                  className="flex px-6 py-3 hover:scale-105 border-2 border-white/20"
                >
                  <RefreshCw className="w-4 h-4" />
                  Try Again
                </Button>
              ) : (
                <Button
                  variant="primary"
                  onClick={this.handleRefresh}
                  className="flex px-6 py-3 hover:scale-105 border-2 border-white/20"
                >
                  <RefreshCw className="w-4 h-4" />
                  Refresh Page
                </Button>
              )}

              <Button
                variant="secondary"
                onClick={this.handleGoHome}
                className="flex px-6 py-3 bg-gray-100 text-charcoal-soft hover:bg-gray-200"
              >
                <Home className="w-4 h-4" />
                Go Home
              </Button>
            </div>
          </div>
        </div>
      );
    }

    return this.props.children;
  }
}

// Higher-order component for function components
export function withErrorBoundary<P extends object>(
  WrappedComponent: React.ComponentType<P>,
  fallback?: ReactNode
): React.FC<P> {
  return function WithErrorBoundaryWrapper(props: P) {
    return (
      <ErrorBoundary fallback={fallback}>
        <WrappedComponent {...props} />
      </ErrorBoundary>
    );
  };
}

