      />
    </div>
  );

  return (
    <div className="w-full max-w-4xl mx-auto p-4 md:p-6 pb-24 animate-fadeIn relative">


      <div className="mb-6 md:mb-10 flex items-center gap-3 md:gap-4">
        {onNavigate && (
          <Button
            variant="ghost"
            size="icon"
