          ≡ƒÄ¿ {preset.colorPalette}
        </p>
      )}

      {/* Actions for custom presets */}
      {!preset.isBuiltIn && (onEdit || onDelete) && (
        <div className="flex gap-1 mt-3 pt-3 border-t border-gray-200 dark:border-gray-700">
          {onEdit && (
            <Button
              variant="ghost"
              size="sm"
              onClick={(e) => {
                e.stopPropagation();
                onEdit(preset);
              }}
              className="flex-1 flex gap-1 py-1.5 text-xs hover:bg-gray-100 dark:hover:bg-gray-700 text-gray-600 dark:text-gray-400"
            >
              <Edit2 className="w-3 h-3" />
              Edit
            </Button>
          )}
          {onDelete && (
            <Button
              variant="ghost"
              size="sm"
              onClick={(e) => {
                e.stopPropagation();
                onDelete(preset.id);
              }}
              className="flex-1 flex gap-1 py-1.5 text-xs hover:bg-red-50 dark:hover:bg-red-900/20 text-red-500"
            >
              <Trash2 className="w-3 h-3" />
              Delete
            </Button>
          )}
        </div>
      )}

      {/* Built-in badge */}
      {preset.isBuiltIn && (
        <div className={`mt-2 text-xs ${isSelected ? 'text-white/60' : 'text-gray-400'}`}>
          Γ£¿ Built-in preset
        </div>
      )}
    </motion.div>
  );
};

// Style Preset Picker Modal
interface StylePresetPickerProps {
  isOpen: boolean;
  onClose: () => void;
  onSelect: (preset: StylePreset) => void;
  selectedId?: string;
}

export const StylePresetPicker: React.FC<StylePresetPickerProps> = ({
  isOpen,
  onClose,
  onSelect,
  selectedId,
}) => {
  const { presets, favorites, recent: _recent, toggleFavorite, addPreset, deletePreset } = useStylePresets();
  const [activeTab, setActiveTab] = useState<'all' | 'favorites' | 'custom'>('all');
  const [isCreating, setIsCreating] = useState(false);
  const [newPreset, setNewPreset] = useState({ name: '', style: '', description: '' });

  const handleSelect = (preset: StylePreset) => {
    onSelect(preset);
    onClose();
  };

  const handleCreate = () => {
    if (newPreset.name && newPreset.style) {
      addPreset({
        name: newPreset.name,
        style: newPreset.style,
        description: newPreset.description,
        isFavorite: false,
      });
      setNewPreset({ name: '', style: '', description: '' });
      setIsCreating(false);
    }
  };

  const displayPresets =
    activeTab === 'favorites'
      ? favorites
      : activeTab === 'custom'
        ? presets.filter((p) => !p.isBuiltIn)
        : presets;

  if (!isOpen) return null;

  return (
    <AnimatePresence>
      <motion.div
        className="fixed inset-0 z-200 flex items-center justify-center p-4"
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        exit={{ opacity: 0 }}
      >
        <motion.div className="absolute inset-0 bg-black/60 backdrop-blur-sm" onClick={onClose} />

        <motion.div
          className="relative bg-white dark:bg-gray-900 rounded-3xl border-2 border-peach-soft w-full max-w-4xl max-h-[90vh] md:max-h-[85vh] overflow-hidden flex flex-col"
          initial={{ scale: 0.9, opacity: 0 }}
          animate={{ scale: 1, opacity: 1 }}
          exit={{ scale: 0.9, opacity: 0 }}
        >
          {/* Header */}
          <div className="p-4 md:p-6 border-b border-gray-200 dark:border-gray-700 shrink-0">
            <div className="flex items-center justify-between mb-4">
              <div className="flex items-center gap-3">
                <div className="p-2 bg-coral-burst/10 rounded-xl">
                  <Palette className="w-6 h-6 text-coral-burst" />
                </div>
                <div>
                  <h2 className="text-lg md:text-xl font-bold text-gray-900 dark:text-white">
                    Style Presets
                  </h2>
                  <p className="text-xs md:text-sm text-gray-500 dark:text-gray-400">
                    Choose an illustration style for your book
                  </p>
                </div>
              </div>
              <Button
                variant="ghost"
                size="icon"
                onClick={onClose}
                title="Close"
                className="p-2 hover:bg-gray-100 dark:hover:bg-gray-800"
              >
                <X className="w-5 h-5 text-gray-500" />
              </Button>
            </div>

            {/* Tabs */}
            <div className="flex gap-2 overflow-x-auto pb-2 md:pb-0 no-scrollbar">
              {[
                { id: 'all', label: 'All Styles', count: presets.length },
                { id: 'favorites', label: 'Favorites', count: favorites.length },
                {
                  id: 'custom',
                  label: 'My Styles',
                  count: presets.filter((p) => !p.isBuiltIn).length,
                },
              ].map((tab) => (
                <Button
                  variant="ghost"
                  key={tab.id}
                  onClick={() => setActiveTab(tab.id as 'all' | 'favorites' | 'custom')}
                  className={`
                                        px-4 py-2 whitespace-nowrap
                                        ${
                                          activeTab === tab.id
                                            ? 'bg-coral-burst text-white'
                                            : 'bg-gray-100 dark:bg-gray-800 text-gray-600 dark:text-gray-400 hover:bg-gray-200 dark:hover:bg-gray-700'
                                        }
                                    `}
                >
                  {tab.label} ({tab.count})
                </Button>
              ))}
              <Button
                variant="default"
                size="sm"
                onClick={() => setIsCreating(true)}
                className="ml-auto flex px-4 py-2 bg-green-500 text-white hover:bg-green-600 whitespace-nowrap"
              >
                <Plus className="w-4 h-4" />
                Create Style
              </Button>
            </div>
          </div>

          {/* Content */}
          <div className="p-4 md:p-6 overflow-y-auto flex-1">
            {isCreating ? (
              <div className="max-w-lg mx-auto space-y-4">
                <h3 className="text-lg font-semibold text-gray-900 dark:text-white">
                  Create New Style
                </h3>
                <div>
                  <Label className="text-gray-700 dark:text-gray-300 mb-1">
                    Style Name
                  </Label>
                  <Input
                    type="text"
                    value={newPreset.name}
                    onChange={(e) => setNewPreset((prev) => ({ ...prev, name: e.target.value }))}
                    placeholder="My Custom Style"
                    className="py-2 border-gray-300 dark:border-gray-600 dark:bg-gray-800 text-gray-900 dark:text-white"
                  />
                </div>
                <div>
                  <Label className="text-gray-700 dark:text-gray-300 mb-1">
                    Style Description (for AI)
                  </Label>
                  <Textarea
                    value={newPreset.style}
                    onChange={(e) => setNewPreset((prev) => ({ ...prev, style: e.target.value }))}
                    placeholder="Describe the illustration style in detail..."
                    rows={3}
                    className="py-2 border-gray-300 dark:border-gray-600 dark:bg-gray-800 text-gray-900 dark:text-white"
                  />
                </div>
                <div>
                  <Label className="text-gray-700 dark:text-gray-300 mb-1">
                    Short Description (optional)
                  </Label>
                  <Input
                    type="text"
                    value={newPreset.description}
                    onChange={(e) =>
                      setNewPreset((prev) => ({ ...prev, description: e.target.value }))
                    }
                    placeholder="A brief description of this style"
                    className="py-2 border-gray-300 dark:border-gray-600 dark:bg-gray-800 text-gray-900 dark:text-white"
                  />
                </div>
                <div className="flex gap-3">
                  <Button
                    variant="outline"
                    onClick={() => setIsCreating(false)}
                    className="flex-1 py-2 border-gray-300 dark:border-gray-600 text-gray-700 dark:text-gray-300"
                  >
                    Cancel
                  </Button>
                  <Button
                    variant="primary"
                    onClick={handleCreate}
                    disabled={!newPreset.name || !newPreset.style}
                    className="flex-1 py-2 bg-coral-burst text-white"
                  >
                    Create Style
                  </Button>
                </div>
              </div>
            ) : (
              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
                {displayPresets.map((preset) => (
                  <PresetCard
                    key={preset.id}
                    preset={preset}
                    onSelect={handleSelect}
                    onToggleFavorite={toggleFavorite}
                    onDelete={preset.isBuiltIn ? undefined : deletePreset}
                    isSelected={preset.id === selectedId}
                  />
                ))}
                {displayPresets.length === 0 && (
                  <div className="col-span-full text-center py-12 text-gray-500">
                    <Palette className="w-12 h-12 mx-auto mb-3 opacity-50" />
                    <p>No styles found in this category</p>
                  </div>
                )}
              </div>
            )}
          </div>
        </motion.div>
      </motion.div>
    </AnimatePresence>
  );
};

