interface TemplateLibraryProps {
  isOpen: boolean;
  onClose: () => void;
  onSelectTemplate: (template: BookTemplate) => void;
}

const TemplateLibrary: React.FC<TemplateLibraryProps> = ({ isOpen, onClose, onSelectTemplate }) => {
  const [selectedCategory, setSelectedCategory] = useState<string>('all');
  const [selectedTemplate, setSelectedTemplate] = useState<BookTemplate | null>(null);

  const categories = ['all', 'adventure', 'educational', 'bedtime', 'fairy-tale'];

  const filteredTemplates =
    selectedCategory === 'all'
      ? bookTemplates
      : bookTemplates.filter((t) => t.category === selectedCategory);

  const handleUseTemplate = () => {
    if (selectedTemplate) {
      onSelectTemplate(selectedTemplate);
      onClose();
    }
  };

  if (!isOpen) return null;

  return (
    <AnimatePresence>
      <motion.div
        className="fixed inset-0 z-100 flex items-center justify-center p-4"
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        exit={{ opacity: 0 }}
      >
        <motion.div className="absolute inset-0 bg-black/60 backdrop-blur-sm" onClick={onClose} />

        <motion.div
          className="relative bg-white dark:bg-gray-900 rounded-3xl border-2 border-peach-soft w-full max-w-5xl max-h-[90vh] overflow-hidden flex flex-col"
          initial={{ scale: 0.9, opacity: 0 }}
          animate={{ scale: 1, opacity: 1 }}
          exit={{ scale: 0.9, opacity: 0 }}
        >
          {/* Header */}
          <div className="shrink-0 p-4 border-b border-gray-200 md:p-6 dark:border-gray-700">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-3">
                <div className="p-2 bg-linear-to-br from-coral-burst to-sunset-coral rounded-xl">
                  <Wand2 className="w-6 h-6 text-white" />
                </div>
                <div>
                  <h2 className="text-lg font-bold text-gray-900 md:text-2xl dark:text-white">
                    Template Library
                  </h2>
                  <p className="text-xs text-gray-500 md:text-sm dark:text-gray-400">
                    Start with a proven story structure
                  </p>
                </div>
              </div>
              <Button
                onClick={onClose}
                title="Close"
                variant="ghost"
                size="icon"
                className="p-2 hover:bg-gray-100 dark:hover:bg-gray-800"
              >
                <X className="w-6 h-6 text-gray-500" />
              </Button>
            </div>

            {/* Category filters */}
            <div className="flex gap-2 pb-2 mt-4 overflow-x-auto no-scrollbar">
              {categories.map((cat) => (
                <Button
                  key={cat}
                  onClick={() => setSelectedCategory(cat)}
                  variant="ghost"
                  size="sm"
                  className={`
                                        px-4 py-2 rounded-full font-medium whitespace-nowrap
                                        ${
                                          selectedCategory === cat
                                            ? 'bg-coral-burst text-white'
                                            : 'bg-gray-100 dark:bg-gray-800 text-gray-600 dark:text-gray-400 hover:bg-gray-200 dark:hover:bg-gray-700'
                                        }
                                    `}
                >
                  {cat === 'all'
                    ? 'All Templates'
                    : categoryLabels[cat as keyof typeof categoryLabels]}
                </Button>
              ))}
            </div>
          </div>

          {/* Content */}
          <div className="flex-1 p-4 overflow-y-auto md:p-6">
            <div className="grid grid-cols-1 gap-4 md:grid-cols-2 lg:grid-cols-3">
              {filteredTemplates.map((template) => (
                <motion.div
                  key={template.id}
                  whileHover={{ scale: 1.02 }}
                  whileTap={{ scale: 0.98 }}
                  onClick={() => setSelectedTemplate(template)}
                  className={`
                                        relative p-4 rounded-2xl border-2 cursor-pointer transition-all
                                        ${
                                          selectedTemplate?.id === template.id
                                            ? 'border-coral-burst bg-coral-burst/5'
                                            : 'border-gray-200 dark:border-gray-700 hover:border-coral-burst/50'
                                        }
                                    `}
                >
                  {/* Badges */}
                  <div className="absolute flex gap-2 top-3 right-3">
                    {template.popular && (
                      <span className="px-2 py-0.5 text-xs font-bold bg-yellow-100 text-yellow-700 dark:bg-yellow-900/30 dark:text-yellow-400 rounded-full flex items-center gap-1">
                        <Star className="w-3 h-3" /> Popular
                      </span>
                    )}
                    {template.new && (
                      <span className="px-2 py-0.5 text-xs font-bold bg-green-100 text-green-700 dark:bg-green-900/30 dark:text-green-400 rounded-full flex items-center gap-1">
                        <Sparkles className="w-3 h-3" /> New
                      </span>
                    )}
                  </div>

                  {/* Icon */}
                  <div
                    className={`
                                        w-12 h-12 rounded-xl bg-linear-to-br ${categoryColors[template.category]}
                                        flex items-center justify-center text-white mb-3
                                    `}
                  >
                    {template.icon}
                  </div>

                  {/* Info */}
                  <h3 className="mb-1 font-bold text-gray-900 dark:text-white">{template.name}</h3>
                  <p className="mb-3 text-sm text-gray-500 dark:text-gray-400">
                    {template.description}
                  </p>

                  {/* Meta */}
                  <div className="flex items-center gap-4 text-xs text-gray-400">
                    <span className="flex items-center gap-1">
                      <BookOpen className="w-3 h-3" />
                      {template.pageCount} pages
                    </span>
                    <span className="flex items-center gap-1">
                      <Users className="w-3 h-3" />
                      {template.ageRange}
                    </span>
                  </div>

                  {/* Selection indicator */}
                  {selectedTemplate?.id === template.id && (
                    <div className="absolute top-4 left-4">
                      <div className="flex items-center justify-center w-6 h-6 rounded-full bg-coral-burst">
                        <Check className="w-4 h-4 text-white" />
                      </div>
                    </div>
                  )}
                </motion.div>
              ))}
            </div>
          </div>

          {/* Preview panel when template selected */}
          <AnimatePresence>
            {selectedTemplate && (
              <motion.div
                initial={{ height: 0, opacity: 0 }}
                animate={{ height: 'auto', opacity: 1 }}
                exit={{ height: 0, opacity: 0 }}
                className="shrink-0 border-t border-gray-200 dark:border-gray-700 bg-gray-50 dark:bg-gray-800/50"
              >
                <div className="p-4 md:p-6">
                  <div className="flex flex-col items-start justify-between gap-4 md:flex-row md:gap-6">
                    <div className="flex-1 w-full">
                      <h3 className="mb-2 text-lg font-bold text-gray-900 dark:text-white">
                        {selectedTemplate.name} Structure
                      </h3>
                      <p className="mb-4 text-sm text-gray-500 dark:text-gray-400">
                        Example prompt: "{selectedTemplate.samplePrompt}"
                      </p>

                      {/* Structure preview */}
                      <div className="flex gap-2 pb-2 overflow-x-auto no-scrollbar">
                        {selectedTemplate.structure.slice(0, 6).map((page, i) => (
                          <div
                            key={i}
                            className="shrink-0 w-24 p-2 bg-white border border-gray-200 rounded-lg dark:bg-gray-800 dark:border-gray-700"
                          >
                            <div className="mb-1 text-xs font-bold text-coral-burst">
                              Page {page.pageNumber}
                            </div>
                            <div className="text-xs text-gray-500 dark:text-gray-400 line-clamp-2">
                              {page.suggestedContent}
                            </div>
                          </div>
                        ))}
                        {selectedTemplate.structure.length > 6 && (
                          <div className="flex items-center justify-center shrink-0 w-24 p-2 bg-gray-100 rounded-lg dark:bg-gray-700">
                            <span className="text-xs text-gray-500 dark:text-gray-400">
                              +{selectedTemplate.structure.length - 6} more
                            </span>
                          </div>
                        )}
                      </div>
                    </div>

                    <Button
                      onClick={handleUseTemplate}
                      variant="primary"
                      className="w-full px-6 py-3 text-white md:w-auto bg-linear-to-r from-coral-burst to-sunset-coral border-2 border-white/20"
                    >
                      Use Template
                      <ArrowRight className="w-5 h-5" />
                    </Button>
                  </div>
                </div>
              </motion.div>
            )}
          </AnimatePresence>
        </motion.div>
      </motion.div>
    </AnimatePresence>
  );
};

export default TemplateLibrary;

import { motion } from 'framer-motion';
import { Bug, ChevronRight, Gift, Sparkles, Star, Wrench, Zap } from 'lucide-react';
