// =============================================================================
// HOOKS FOR ROOM FEATURES
// =============================================================================

/**
 * Hook to broadcast events to all users in the room
 */
export function useRoomBroadcast() {
  const broadcast = useBroadcastEvent();

  return {
    broadcastChapterSaved: (chapterId: string) =>
      broadcast({ type: 'CHAPTER_SAVED', data: { chapterId }, timestamp: Date.now() }),

    broadcastContentRegenerated: (elementId: string) =>
      broadcast({ type: 'CONTENT_REGENERATED', data: { elementId }, timestamp: Date.now() }),

    broadcastUndo: () => broadcast({ type: 'UNDO', timestamp: Date.now() }),

    broadcastRedo: () => broadcast({ type: 'REDO', timestamp: Date.now() }),

    broadcastCustom: (event: RoomEvent) => broadcast({ ...event, timestamp: Date.now() }),
  };
}

/**
 * Hook to listen for room events
 */
export function useRoomEvents(handlers: {
  onChapterSaved?: (chapterId: string) => void;
  onContentRegenerated?: (elementId: string) => void;
  onUndo?: () => void;
  onRedo?: () => void;
  onCustom?: (event: RoomEvent) => void;
}) {
  useEventListener(({ event }) => {
    const eventData = event.data as { chapterId?: string; elementId?: string } | undefined;
    switch (event.type) {
      case 'CHAPTER_SAVED':
        handlers.onChapterSaved?.(eventData?.chapterId || '');
        break;
      case 'CONTENT_REGENERATED':
        handlers.onContentRegenerated?.(eventData?.elementId || '');
        break;
      case 'UNDO':
        handlers.onUndo?.();
        break;
      case 'REDO':
        handlers.onRedo?.();
        break;
      default:
        handlers.onCustom?.(event);
    }
  });
}

/**
 * Hook to manage selection state
 */
export function useSelection() {
  const [presence] = useMyPresence();
  const updateMyPresence = useUpdateMyPresence();

  return {
    selectedIds: presence.selectedIds,

    select: (id: string) => {
      updateMyPresence({ selectedIds: [id] });
    },

    addToSelection: (id: string) => {
      updateMyPresence({
        selectedIds: [...(presence.selectedIds || []), id].filter((v, i, a) => a.indexOf(v) === i),
      });
    },

    removeFromSelection: (id: string) => {
      updateMyPresence({
        selectedIds: (presence.selectedIds || []).filter((selectedId) => selectedId !== id),
      });
    },

    clearSelection: () => {
      updateMyPresence({ selectedIds: [] });
    },

    isSelected: (id: string) => (presence.selectedIds || []).includes(id),
  };
}

/**
 * Hook to manage editing state
 */
export function useEditingState() {
  const [presence] = useMyPresence();
  const updateMyPresence = useUpdateMyPresence();

  return {
    isEditing: presence.isEditing,
    editingElementId: presence.editingElementId,

    startEditing: (elementId: string) => {
      updateMyPresence({ isEditing: true, editingElementId: elementId });
    },

    stopEditing: () => {
      updateMyPresence({ isEditing: false, editingElementId: undefined });
    },
  };
}

export default CollaborativeRoom;

import {
  ChevronDown,
  ChevronRight,
  Clock,
  Copy,
  Eye,
  GitBranch,
  GitCommit,
  GitMerge,
  Maximize2,
  Minimize2,
  RotateCcw,
  Star,
  X,
  ZoomIn,
  ZoomOut,
} from 'lucide-react';
import type React from 'react';
import { useEffect, useMemo, useState } from 'react';
import { versionControlService } from '../../services/versionControlService';
import type { VersionNode, VisualBranch, VisualVersion } from '../../types/advanced';
import { Button } from '@/components/ui/button';

interface FamilyTreeViewerProps {
  visualId: string;
  isOpen: boolean;
  onClose: () => void;
  onRestoreVersion?: (version: VisualVersion) => void;
  onForkVersion?: (version: VisualVersion) => void;
}

export const FamilyTreeViewer: React.FC<FamilyTreeViewerProps> = ({
  visualId,
  isOpen,
  onClose,
  onRestoreVersion,
  onForkVersion,
}) => {
  const [versions, setVersions] = useState<VisualVersion[]>([]);
  const [branches, setBranches] = useState<VisualBranch[]>([]);
  const [familyTree, setFamilyTree] = useState<VersionNode | null>(null);
  const [selectedVersion, setSelectedVersion] = useState<VisualVersion | null>(null);
  const [compareVersion, setCompareVersion] = useState<VisualVersion | null>(null);
  const [isComparing, setIsComparing] = useState(false);
  const [viewMode, setViewMode] = useState<'tree' | 'timeline' | 'branches'>('timeline');
  const [loading, setLoading] = useState(true);
  const [zoom, setZoom] = useState(1);
  const [isFullscreen, setIsFullscreen] = useState(false);
  const [expandedBranches, setExpandedBranches] = useState<Set<string>>(new Set(['main']));

  useEffect(() => {
    if (isOpen && visualId) {
      loadVersionHistory();
    }
  }, [isOpen, visualId]);

  const loadVersionHistory = async () => {
    setLoading(true);
    try {
      const [history, branchList, tree] = await Promise.all([
        versionControlService.getVersions(visualId),
        versionControlService.getBranches(visualId),
        versionControlService.getFamilyTree(visualId),
      ]);

      setVersions(history);
      setBranches(branchList);
      // Convert FamilyTree to VersionNode format
      if (tree && tree.root) {
        setFamilyTree(tree.root as unknown as VersionNode);
      }
    } catch (error) {
      console.error('Error loading version history:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleRestore = async (version: VisualVersion) => {
    try {
      await versionControlService.restoreVersion(visualId, version.id);
      onRestoreVersion?.(version);
      await loadVersionHistory();
    } catch (error) {
      console.error('Error restoring version:', error);
    }
  };

  const handleFork = async (version: VisualVersion) => {
    try {
      const branchName = `fork-${Date.now()}`;
      await versionControlService.createBranch(visualId, branchName, version.id);
      onForkVersion?.(version);
      await loadVersionHistory();
    } catch (error) {
      console.error('Error forking version:', error);
    }
  };

  const handleCompare = (version: VisualVersion) => {
    if (!isComparing) {
      setCompareVersion(version);
      setIsComparing(true);
    } else if (compareVersion && compareVersion.id !== version.id) {
      // Show comparison
      setSelectedVersion(version);
    }
  };

  const cancelCompare = () => {
    setIsComparing(false);
    setCompareVersion(null);
  };

  const toggleBranch = (branchName: string) => {
    setExpandedBranches((prev) => {
      const next = new Set(prev);
      if (next.has(branchName)) {
        next.delete(branchName);
      } else {
        next.add(branchName);
      }
      return next;
    });
  };

  const groupedVersions = useMemo(() => {
    const groups: Record<string, VisualVersion[]> = {};
    versions.forEach((v) => {
      const branch = v.branch_name || 'main';
      if (!groups[branch]) groups[branch] = [];
      groups[branch].push(v);
    });
    return groups;
  }, [versions]);

  const formatDate = (date: string) => {
    const d = new Date(date);
    const now = new Date();
    const diff = now.getTime() - d.getTime();

    if (diff < 60000) return 'Just now';
    if (diff < 3600000) return `${Math.floor(diff / 60000)}m ago`;
    if (diff < 86400000) return `${Math.floor(diff / 3600000)}h ago`;
    if (diff < 604800000) return `${Math.floor(diff / 86400000)}d ago`;

    return d.toLocaleDateString();
  };

  if (!isOpen) return null;

  return (
    <div
      className={`fixed inset-0 bg-black/50 backdrop-blur-sm z-50 flex items-center justify-center ${
        isFullscreen ? 'p-0' : 'p-4'
      }`}
    >
      <div
        className={`bg-gray-900 rounded-2xl overflow-hidden flex flex-col ${
          isFullscreen ? 'w-full h-full rounded-none' : 'w-full max-w-5xl max-h-[90vh]'
        }`}
        onClick={(e) => e.stopPropagation()}
      >
        {/* Header */}
        <div className="p-4 border-b border-gray-800 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 bg-linear-to-br from-green-500 to-emerald-500 rounded-xl flex items-center justify-center">
              <GitBranch className="w-5 h-5 text-white" />
            </div>
            <div>
              <h2 className="text-lg font-bold text-white">Version History</h2>
              <p className="text-gray-400 text-sm">
                {versions.length} versions ΓÇó {branches.length} branches
              </p>
            </div>
          </div>

          <div className="flex items-center gap-2">
            {/* View Mode Tabs */}
            <div className="flex bg-gray-800 rounded-lg p-1">
              {[
                { id: 'timeline', label: 'Timeline', icon: Clock },
                { id: 'branches', label: 'Branches', icon: GitBranch },
                { id: 'tree', label: 'Tree', icon: GitMerge },
              ].map((mode) => (
                <Button
                  key={mode.id}
                  variant="ghost"
                  size="sm"
                  onClick={() => setViewMode(mode.id as typeof viewMode)}
                  className={`flex gap-1.5 px-3 py-1.5 ${
                    viewMode === mode.id
                      ? 'bg-gray-700 text-white'
                      : 'text-gray-400 hover:text-gray-300'
                  }`}
                >
                  <mode.icon className="w-4 h-4" />
                  {mode.label}
                </Button>
              ))}
            </div>

            {/* Zoom Controls */}
            <div className="flex items-center gap-1 ml-2">
              <Button
                variant="ghost"
                size="icon"
                onClick={() => setZoom((z) => Math.max(0.5, z - 0.1))}
                className="p-1.5 hover:bg-gray-800"
              >
                <ZoomOut className="w-4 h-4 text-gray-400" />
              </Button>
              <span className="text-xs text-gray-500 w-12 text-center">
                {Math.round(zoom * 100)}%
              </span>
              <Button
                variant="ghost"
                size="icon"
                onClick={() => setZoom((z) => Math.min(2, z + 0.1))}
                className="p-1.5 hover:bg-gray-800"
              >
                <ZoomIn className="w-4 h-4 text-gray-400" />
              </Button>
            </div>

            <Button
              variant="ghost"
              size="icon"
              onClick={() => setIsFullscreen(!isFullscreen)}
              className="p-2 hover:bg-gray-800"
            >
              {isFullscreen ? (
                <Minimize2 className="w-5 h-5 text-gray-400" />
              ) : (
                <Maximize2 className="w-5 h-5 text-gray-400" />
              )}
            </Button>

            <Button
              variant="ghost"
              size="icon"
              onClick={onClose}
              className="p-2 hover:bg-gray-800"
            >
              <X className="w-5 h-5 text-gray-400" />
            </Button>
          </div>
        </div>

        {/* Compare Mode Banner */}
        {isComparing && (
          <div className="px-4 py-2 bg-blue-500/20 border-b border-blue-500/30 flex items-center justify-between">
            <p className="text-sm text-blue-300">
              <span className="font-medium">Compare Mode:</span> Select another version to compare
              with "{compareVersion?.version_name || `v${compareVersion?.version_number}`}"
            </p>
            <Button variant="ghost" size="sm" onClick={cancelCompare} className="text-blue-400 hover:text-blue-300">
              Cancel
            </Button>
          </div>
        )}

        {/* Content */}
        <div className="flex-1 overflow-hidden flex">
          {loading ? (
            <div className="flex-1 flex items-center justify-center">
              <div className="animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-green-500"></div>
            </div>
          ) : (
            <>
              {/* Main View */}
              <div
                className="flex-1 overflow-auto p-4"
                style={{ transform: `scale(${zoom})`, transformOrigin: 'top left' }}
              >
                {/* Timeline View */}
                {viewMode === 'timeline' && (
                  <div className="space-y-4 max-w-2xl mx-auto">
                    {versions.map((version, index) => (
                      <VersionCard
                        key={version.id}
                        version={version}
                        isFirst={index === 0}
                        isLast={index === versions.length - 1}
                        isSelected={selectedVersion?.id === version.id}
                        isCompareTarget={compareVersion?.id === version.id}
                        isComparing={isComparing}
                        onSelect={() => setSelectedVersion(version)}
                        onRestore={() => handleRestore(version)}
                        onFork={() => handleFork(version)}
                        onCompare={() => handleCompare(version)}
                        formatDate={formatDate}
                      />
                    ))}

                    {versions.length === 0 && (
                      <div className="text-center py-12">
                        <GitCommit className="w-12 h-12 text-gray-600 mx-auto mb-4" />
                        <p className="text-gray-400">No versions yet</p>
                        <p className="text-sm text-gray-500">
                          Versions are created when you save changes
                        </p>
                      </div>
                    )}
                  </div>
                )}

                {/* Branches View */}
                {viewMode === 'branches' && (
                  <div className="space-y-4">
                    {Object.entries(groupedVersions).map(([branchName, branchVersions]) => (
                      <div key={branchName} className="bg-gray-800/50 rounded-xl overflow-hidden">
                        <Button
                          variant="ghost"
                          onClick={() => toggleBranch(branchName)}
                          className="w-full px-4 py-3 flex justify-between hover:bg-gray-800/70"
                        >
                          <div className="flex items-center gap-3">
                            <GitBranch className="w-5 h-5 text-green-400" />
                            <span className="font-medium text-white">{branchName}</span>
                            <span className="text-xs text-gray-500">
                              {branchVersions.length} versions
                            </span>
                            {branchName === 'main' && (
                              <span className="px-2 py-0.5 bg-green-500/20 text-green-400 text-xs rounded-full">
                                default
                              </span>
                            )}
                          </div>
                          {expandedBranches.has(branchName) ? (
                            <ChevronDown className="w-5 h-5 text-gray-400" />
                          ) : (
                            <ChevronRight className="w-5 h-5 text-gray-400" />
                          )}
                        </Button>

                        {expandedBranches.has(branchName) && (
                          <div className="px-4 pb-4 space-y-2">
                            {branchVersions.map((version, _index) => (
                              <div
                                key={version.id}
                                className={`p-3 rounded-lg cursor-pointer transition-colors ${
                                  selectedVersion?.id === version.id
                                    ? 'bg-green-500/20 border border-green-500/30'
                                    : 'bg-gray-900/50 hover:bg-gray-900/70'
                                }`}
                                onClick={() => setSelectedVersion(version)}
                              >
                                <div className="flex items-center gap-3">
                                  <GitCommit className="w-4 h-4 text-gray-500" />
                                  <div className="flex-1 min-w-0">
                                    <p className="text-white text-sm font-medium truncate">
                                      {version.version_name || `Version ${version.version_number}`}
                                    </p>
                                    <p className="text-xs text-gray-500">
                                      {formatDate(version.created_at)}
                                    </p>
                                  </div>
                                  {version.is_starred && (
                                    <Star className="w-4 h-4 text-yellow-400 fill-yellow-400" />
                                  )}
                                </div>
                              </div>
                            ))}
                          </div>
                        )}
                      </div>
                    ))}
                  </div>
                )}

                {/* Tree View */}
                {viewMode === 'tree' && familyTree && (
                  <div className="min-w-max">
                    <TreeNode
                      node={familyTree}
                      depth={0}
                      selectedId={selectedVersion?.id}
                      onSelect={(id) => {
                        const version = versions.find((v) => v.id === id);
                        if (version) setSelectedVersion(version);
                      }}
                    />
                  </div>
                )}
              </div>

              {/* Detail Panel */}
              {selectedVersion && (
                <div className="w-80 border-l border-gray-800 overflow-y-auto">
                  <VersionDetailPanel
                    version={selectedVersion}
                    compareWith={isComparing && compareVersion ? compareVersion : undefined}
                    onRestore={() => handleRestore(selectedVersion)}
                    onFork={() => handleFork(selectedVersion)}
                    onClose={() => setSelectedVersion(null)}
                  />
                </div>
              )}
            </>
          )}
        </div>
      </div>
    </div>
  );
};

// Version Card Component
interface VersionCardProps {
