  const [searchQuery, setSearchQuery] = useState('');
  const [filter, setFilter] = useState<'all' | 'complete' | 'rtl'>('all');
  const [changingTo, setChangingTo] = useState<LanguageCode | null>(null);

  // Filter and search languages
  const filteredLanguages = useMemo(() => {
    return SUPPORTED_LANGUAGES.filter((lang) => {
      // Search filter
      const matchesSearch =
        searchQuery === '' ||
        lang.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
        lang.englishName.toLowerCase().includes(searchQuery.toLowerCase()) ||
        lang.code.toLowerCase().includes(searchQuery.toLowerCase());

      // Category filter
      const matchesFilter =
        filter === 'all' ||
        (filter === 'complete' && lang.completionPercentage >= 90) ||
        (filter === 'rtl' && lang.isRTL);

      return matchesSearch && matchesFilter;
    });
  }, [searchQuery, filter]);

  // Handle language selection
  const handleLanguageSelect = async (code: LanguageCode) => {
    if (code === currentLanguage.code || isLoading) return;

    setChangingTo(code);
    try {
      await changeLanguage(code);
      onLanguageChange?.(code);
    } finally {
      setChangingTo(null);
    }
  };

  // Reset to browser default
  const handleReset = async () => {
    const browserLang = navigator.language.split('-')[0] as LanguageCode;
    const supportedLang = getLanguageByCode(browserLang);
    if (supportedLang && supportedLang.code !== currentLanguage.code) {
      await handleLanguageSelect(supportedLang.code);
    }
  };

  // Compact mode - just a dropdown
  if (showCompact) {
    return (
      <Select value={currentLanguage.code} onValueChange={(v) => handleLanguageSelect(v as LanguageCode)} disabled={isLoading}>
        <SelectTrigger aria-label={t('selectLanguage', 'Select language')}>
          <SelectValue placeholder="Select language" />
        </SelectTrigger>
        <SelectContent>
          {SUPPORTED_LANGUAGES.map((lang) => (
            <SelectItem key={lang.code} value={lang.code}>
              {lang.flag} {lang.name}
            </SelectItem>
          ))}
        </SelectContent>
      </Select>
    );
  }

  // Full mode - grid with search and filters
  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 rounded-xl bg-linear-to-br from-coral-burst to-gold-sunshine flex items-center justify-center">
            <Globe className="w-5 h-5 text-white" />
          </div>
          <div>
            <h2 className="font-heading font-bold text-xl text-charcoal-soft">
              {t('language', 'Language')}
            </h2>
            <p className="text-sm text-gray-500">
              {t('languageDescription', 'Choose your preferred language')}
            </p>
          </div>
        </div>

        {/* Reset button */}
        <button
          onClick={handleReset}
          disabled={isLoading}
          className="flex items-center gap-2 px-3 py-2 text-sm text-gray-600 hover:text-gray-800 
            hover:bg-gray-100 rounded-lg transition-colors disabled:opacity-50"
          title={t('resetLanguage', 'Reset to browser default')}
        >
          <RotateCcw className="w-4 h-4" />
          <span className="hidden sm:inline">{t('reset', 'Reset')}</span>
        </button>
      </div>

      {/* Current selection indicator */}
      <div className="flex items-center gap-2 p-3 bg-linear-to-r from-coral-burst/10 to-gold-sunshine/10 rounded-lg border border-coral-burst/20">
        <Check className="w-5 h-5 text-coral-burst" />
        <span className="text-sm text-charcoal-soft">
          {t('currentLanguage', 'Current language:')}
        </span>
        <span className="font-medium text-charcoal-soft">
          {currentLanguage.flag} {currentLanguage.name}
        </span>
      </div>

      {/* Search and filters */}
      <div className="flex flex-col sm:flex-row gap-3">
        {/* Search */}
        <div className="relative flex-1">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
          <Input
            type="text"
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            placeholder={t('searchLanguages', 'Search languages...')}
            className="pl-10 pr-4 border-gray-200 placeholder:text-gray-400 focus:ring-2 focus:ring-coral-burst focus:border-transparent"
            aria-label={t('searchLanguages', 'Search languages')}
          />
        </div>

        {/* Filter buttons */}
        <div className="flex gap-2">
          {(['all', 'complete', 'rtl'] as const).map((filterOption) => (
            <button
              key={filterOption}
              onClick={() => setFilter(filterOption)}
              className={`px-4 py-2.5 text-sm font-medium rounded-lg transition-colors
                ${
                  filter === filterOption
                    ? 'bg-coral-burst text-white'
                    : 'bg-gray-100 text-gray-600 hover:bg-gray-200'
                }`}
              aria-pressed={filter === filterOption ? 'true' : 'false'}
            >
              {filterOption === 'all' && t('all', 'All')}
              {filterOption === 'complete' && t('complete', 'Complete')}
              {filterOption === 'rtl' && t('rtlLanguages', 'RTL')}
            </button>
          ))}
        </div>
      </div>

      {/* Language grid */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4">
        {filteredLanguages.map((lang) => (
          <LanguageCard
            key={lang.code}
            language={lang}
            isActive={lang.code === currentLanguage.code}
            isLoading={changingTo === lang.code}
            onClick={() => handleLanguageSelect(lang.code)}
          />
        ))}
      </div>

      {/* No results */}
      {filteredLanguages.length === 0 && (
        <div className="text-center py-12">
          <Globe className="w-12 h-12 text-gray-300 mx-auto mb-3" />
          <p className="text-gray-500">{t('noLanguagesFound', 'No languages found')}</p>
          <button
            onClick={() => {
              setSearchQuery('');
              setFilter('all');
            }}
            className="mt-2 text-sm text-coral-burst hover:underline"
          >
            {t('clearFilters', 'Clear filters')}
          </button>
        </div>
      )}

      {/* Language stats */}
      <div className="flex flex-wrap gap-4 pt-4 border-t border-gray-100 text-sm text-gray-500">
        <span>
          {t('totalLanguages', '{{count}} languages available', {
            count: SUPPORTED_LANGUAGES.length,
          })}
        </span>
        <span>ΓÇó</span>
        <span>
          {t('completeLanguages', '{{count}} fully translated', {
            count: SUPPORTED_LANGUAGES.filter((l) => l.completionPercentage >= 90).length,
          })}
        </span>
        <span>ΓÇó</span>
        <span>
          {t('rtlSupport', '{{count}} RTL supported', {
            count: SUPPORTED_LANGUAGES.filter((l) => l.isRTL).length,
          })}
        </span>
      </div>
    </div>
  );
};

export default LanguageSelector;

import {
  BarChart3,
  BookOpen,
  Calendar,
  Download,
  Eye,
  Image as ImageIcon,
  Loader2,
  Sparkles,
  Trash2,
  X,
  ZoomIn,
  ZoomOut,
} from 'lucide-react';
import type React from 'react';
import { useEffect, useState } from 'react';
import { createPortal } from 'react-dom';
import {
  type SavedImage,
  type SavedInfographic,
  deleteImage,
  deleteInfographic,
  getAllImages,
  getAllInfographics,
} from '../../services/libraryService';
import { deleteBook, getAllBooks } from '../../services/storageService';
import type { SavedBook } from '../../types';
import { Button } from '../ui/button';

type LibraryTab = 'books' | 'infographics' | 'images';

interface LibraryPanelProps {
  onViewBook?: (book: SavedBook) => void;
  onNavigate?: (mode: string) => void;
}

const LibraryPanel: React.FC<LibraryPanelProps> = ({ onViewBook, onNavigate }) => {
  const [activeTab, setActiveTab] = useState<LibraryTab>('books');
  const [books, setBooks] = useState<SavedBook[]>([]);
  const [infographics, setInfographics] = useState<SavedInfographic[]>([]);
  const [images, setImages] = useState<SavedImage[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [deletingId, setDeletingId] = useState<string | null>(null);

  // Viewer states
  const [viewingInfographic, setViewingInfographic] = useState<SavedInfographic | null>(null);
  const [viewingImage, setViewingImage] = useState<SavedImage | null>(null);
  const [imageZoom, setImageZoom] = useState(1);

  useEffect(() => {
    loadLibrary();
  }, []);

  const loadLibrary = async () => {
    setIsLoading(true);
    try {
      const [booksData, infographicsData, imagesData] = await Promise.all([
        getAllBooks(),
        getAllInfographics(),
        getAllImages(),
      ]);
      setBooks(booksData);
      setInfographics(infographicsData);
      setImages(imagesData);
    } catch (error) {
      console.error('Failed to load library:', error);
    } finally {
      setIsLoading(false);
    }
  };

  const handleDeleteBook = async (id: string) => {
    if (!confirm('Are you sure you want to delete this book?')) return;
    setDeletingId(id);
    try {
      await deleteBook(id);
      setBooks((prev) => prev.filter((b) => b.id !== id));
    } catch (error) {
      console.error('Failed to delete book:', error);
    } finally {
      setDeletingId(null);
    }
  };

  const handleDeleteInfographic = async (id: string) => {
    if (!confirm('Are you sure you want to delete this infographic?')) return;
    setDeletingId(id);
    try {
      await deleteInfographic(id);
      setInfographics((prev) => prev.filter((i) => i.id !== id));
    } catch (error) {
      console.error('Failed to delete infographic:', error);
    } finally {
      setDeletingId(null);
    }
  };

  const handleDeleteImage = async (id: string) => {
    if (!confirm('Are you sure you want to delete this image?')) return;
    setDeletingId(id);
    try {
      await deleteImage(id);
      setImages((prev) => prev.filter((i) => i.id !== id));
    } catch (error) {
      console.error('Failed to delete image:', error);
    } finally {
      setDeletingId(null);
    }
  };

  const formatDate = (date: Date) => {
    return new Date(date).toLocaleDateString('en-US', {
      month: 'short',
      day: 'numeric',
      year: 'numeric',
    });
  };

  const TabButton = ({
    id,
    icon: Icon,
    label,
    count,
  }: { id: LibraryTab; icon: any; label: string; count: number }) => (
    <Button
      variant={activeTab === id ? 'primary' : 'secondary'}
      onClick={() => setActiveTab(id)}
      className={`px-4 py-3 ${
        activeTab === id
          ? 'bg-linear-to-r from-coral-burst to-gold-sunshine text-white border-2 border-white/20'
          : 'bg-cream-soft text-cocoa-light hover:bg-peach-soft/50 hover:text-charcoal-soft'
      }`}
    >
      <Icon className="w-4 h-4" />
      <span>{label}</span>
      <span
        className={`ml-1 px-2 py-0.5 rounded-full text-xs ${
          activeTab === id ? 'bg-white/20' : 'bg-peach-soft'
        }`}
      >
        {count}
      </span>
    </Button>
  );

  const EmptyState = ({
    icon: Icon,
    title,
    description,
  }: { icon: any; title: string; description: string }) => (
    <div className="flex flex-col items-center justify-center py-16 text-center">
      <div className="w-20 h-20 rounded-full bg-cream-soft flex items-center justify-center mb-4">
        <Icon className="w-10 h-10 text-cocoa-light/50" />
      </div>
      <h4 className="font-heading font-bold text-lg text-charcoal-soft mb-2">{title}</h4>
      <p className="text-cocoa-light text-sm max-w-xs">{description}</p>
    </div>
  );

  if (isLoading) {
    return (
      <div className="flex items-center justify-center py-20">
        <Loader2 className="w-8 h-8 text-coral-burst animate-spin" />
      </div>
    );
  }

  return (
    <div className="animate-fadeIn space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h3 className="font-heading font-bold text-xl md:text-2xl text-charcoal-soft flex items-center gap-2">
            <Sparkles className="w-6 h-6 text-gold-sunshine" />
            My Library
          </h3>
          <p className="text-cocoa-light text-sm mt-1">Your saved creations in one place</p>
        </div>
        <div className="text-right">
          <p className="text-2xl font-bold text-charcoal-soft">
            {books.length + infographics.length + images.length}
          </p>
          <p className="text-xs text-cocoa-light">Total Items</p>
        </div>
      </div>

      {/* Tab Navigation */}
      <div className="flex flex-wrap gap-2">
        <TabButton id="books" icon={BookOpen} label="Books" count={books.length} />
        <TabButton
          id="infographics"
          icon={BarChart3}
          label="Infographics"
          count={infographics.length}
        />
        <TabButton id="images" icon={ImageIcon} label="Images" count={images.length} />
      </div>

      {/* Content Area */}
      <div className="min-h-75">
        {/* Books Tab */}
        {activeTab === 'books' && (
          <div className="space-y-4">
            {books.length === 0 ? (
              <EmptyState
                icon={BookOpen}
                title="No books yet"
                description="Create your first storybook and it will appear here"
              />
            ) : (
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                {books.map((book) => (
                  <div
                    key={book.id}
                    className="group bg-cream-soft rounded-2xl p-4 border border-peach-soft/30 hover:border-coral-burst/30 transition-all cursor-pointer"
                    onClick={() => onViewBook?.(book)}
                  >
                    <div className="flex gap-4">
                      {/* Cover */}
                      <div className="w-20 h-28 rounded-xl bg-linear-to-br from-coral-burst/20 to-gold-sunshine/20 shrink-0 overflow-hidden">
                        {book.coverImage ? (
                          <img
                            src={book.coverImage}
                            alt={book.title}
                            className="w-full h-full object-cover"
                          />
                        ) : (
                          <div className="w-full h-full flex items-center justify-center">
                            <BookOpen className="w-8 h-8 text-coral-burst/50" />
                          </div>
                        )}
                      </div>
                      {/* Info */}
                      <div className="flex-1 min-w-0">
                        <h4 className="font-heading font-bold text-charcoal-soft truncate">
                          {book.title}
                        </h4>
                        <p className="text-xs text-cocoa-light mt-1 line-clamp-2">
                          {book.synopsis || 'No description'}
                        </p>
                        <div className="flex items-center gap-1 mt-2 text-xs text-cocoa-light">
                          <Calendar className="w-3 h-3" />
                          {formatDate(book.savedAt)}
                        </div>
                        {/* Actions */}
                        <div className="flex gap-2 mt-3">
                          <Button
                            variant="secondary"
                            size="sm"
                            onClick={(e) => {
                              e.stopPropagation();
                              onViewBook?.(book);
                            }}
                            className="px-3 py-1.5 bg-white text-coral-burst hover:bg-coral-burst hover:text-white"
                          >
                            <Eye className="w-3 h-3" />
                            View
                          </Button>
                          <Button
                            variant="destructive"
                            size="sm"
                            onClick={(e) => {
                              e.stopPropagation();
                              handleDeleteBook(book.id);
                            }}
                            disabled={deletingId === book.id}
                            className="px-3 py-1.5 bg-white text-red-500 hover:bg-red-500 hover:text-white"
                          >
                            {deletingId === book.id ? (
                              <Loader2 className="w-3 h-3 animate-spin" />
                            ) : (
                              <Trash2 className="w-3 h-3" />
                            )}
                            Delete
                          </Button>
                        </div>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        )}

        {/* Infographics Tab */}
        {activeTab === 'infographics' && (
          <div className="space-y-4">
            {infographics.length === 0 ? (
              <EmptyState
                icon={BarChart3}
                title="No infographics yet"
                description="Create an infographic and save it to see it here"
              />
            ) : (
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                {infographics.map((infographic) => (
                  <div
                    key={infographic.id}
                    className="group bg-cream-soft rounded-2xl p-4 border border-peach-soft/30 hover:border-coral-burst/30 transition-all cursor-pointer"
                    onClick={() => setViewingInfographic(infographic)}
                  >
                    <div className="flex gap-4">
                      {/* Thumbnail */}
                      <div className="w-20 h-20 rounded-xl bg-linear-to-br from-blue-100 to-purple-100 shrink-0 flex items-center justify-center">
                        <BarChart3 className="w-8 h-8 text-purple-500/50" />
                      </div>
                      {/* Info */}
                      <div className="flex-1 min-w-0">
                        <h4 className="font-heading font-bold text-charcoal-soft truncate">
                          {infographic.title}
                        </h4>
                        <p className="text-xs text-cocoa-light mt-1">{infographic.topic}</p>
                        <div className="flex items-center gap-2 mt-1">
                          <span className="px-2 py-0.5 bg-purple-100 text-purple-600 rounded-full text-[10px] font-bold uppercase">
                            {infographic.type}
                          </span>
                        </div>
                        <div className="flex items-center gap-1 mt-2 text-xs text-cocoa-light">
                          <Calendar className="w-3 h-3" />
                          {formatDate(infographic.savedAt)}
                        </div>
                        {/* Actions */}
                        <div className="flex gap-2 mt-3">
                          <Button
                            variant="secondary"
                            size="sm"
                            onClick={(e) => {
                              e.stopPropagation();
                              setViewingInfographic(infographic);
                            }}
                            className="px-3 py-1.5 bg-white text-purple-600 hover:bg-purple-600 hover:text-white"
                          >
                            <Eye className="w-3 h-3" />
                            View
                          </Button>
                          <Button
                            variant="destructive"
                            size="sm"
                            onClick={(e) => {
                              e.stopPropagation();
                              handleDeleteInfographic(infographic.id);
                            }}
                            disabled={deletingId === infographic.id}
                            className="px-3 py-1.5 bg-white text-red-500 hover:bg-red-500 hover:text-white"
                          >
                            {deletingId === infographic.id ? (
                              <Loader2 className="w-3 h-3 animate-spin" />
                            ) : (
                              <Trash2 className="w-3 h-3" />
                            )}
                            Delete
                          </Button>
                        </div>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        )}

        {/* Images Tab */}
        {activeTab === 'images' && (
          <div className="space-y-4">
            {images.length === 0 ? (
              <EmptyState
                icon={ImageIcon}
                title="No images yet"
                description="Save images from Visual Studio to build your collection"
              />
            ) : (
              <div className="grid grid-cols-2 sm:grid-cols-3 gap-4">
                {images.map((image) => (
                  <div
                    key={image.id}
                    className="group relative rounded-2xl overflow-hidden border border-peach-soft/30 hover:border-coral-burst/30 transition-all aspect-square cursor-pointer"
                    onClick={() => setViewingImage(image)}
                  >
                    <img
                      src={image.imageUrl}
                      alt={image.title}
                      className="w-full h-full object-cover"
                    />
                    {/* Overlay */}
                    <div className="absolute inset-0 bg-linear-to-t from-black/70 via-black/20 to-transparent opacity-0 group-hover:opacity-100 transition-opacity flex flex-col justify-end p-3">
                      <p className="text-white text-sm font-bold truncate">{image.title}</p>
                      <p className="text-white/70 text-xs truncate">{image.prompt}</p>
                      <div className="flex gap-2 mt-2">
                        <Button
                          variant="ghost"
                          size="icon"
                          onClick={(e) => {
                            e.stopPropagation();
                            setViewingImage(image);
                          }}
                          className="px-2 py-1 bg-white/20 backdrop-blur-sm text-white hover:bg-white/30"
                        >
                          <Eye className="w-3 h-3" />
                        </Button>
                        <a
                          href={image.imageUrl}
                          download={`${image.title}.png`}
                          onClick={(e) => e.stopPropagation()}
                          className="flex items-center gap-1 px-2 py-1 bg-white/20 backdrop-blur-sm rounded-lg text-xs text-white hover:bg-white/30 transition-colors"
                        >
                          <Download className="w-3 h-3" />
                        </a>
                        <Button
                          variant="destructive"
                          size="icon"
                          onClick={(e) => {
                            e.stopPropagation();
                            handleDeleteImage(image.id);
                          }}
                          disabled={deletingId === image.id}
                          className="px-2 py-1 bg-red-500/80 backdrop-blur-sm text-white hover:bg-red-500"
                        >
                          {deletingId === image.id ? (
                            <Loader2 className="w-3 h-3 animate-spin" />
                          ) : (
                            <Trash2 className="w-3 h-3" />
                          )}
                        </Button>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        )}
      </div>

      {/* Image Viewer Modal */}
      {viewingImage &&
        createPortal(
          <div
            className="fixed inset-0 z-100 bg-black/90 flex items-center justify-center animate-fadeIn"
            onClick={() => {
              setViewingImage(null);
              setImageZoom(1);
            }}
          >
            {/* Close button */}
            <Button
              variant="ghost"
              size="icon"
              className="absolute top-4 right-4 p-3 bg-white/10 hover:bg-white/20 text-white z-10"
              onClick={() => {
                setViewingImage(null);
                setImageZoom(1);
              }}
            >
              <X className="w-6 h-6" />
            </Button>

            {/* Zoom controls */}
            <div className="absolute bottom-6 left-1/2 -translate-x-1/2 flex items-center gap-3 bg-white/10 backdrop-blur-md rounded-full px-4 py-2 z-10">
              <Button
                variant="ghost"
                size="icon"
                onClick={(e) => {
                  e.stopPropagation();
                  setImageZoom((z) => Math.max(0.5, z - 0.25));
                }}
                className="p-2 hover:bg-white/20 text-white"
              >
                <ZoomOut className="w-5 h-5" />
              </Button>
              <span className="text-white text-sm font-bold min-w-[60px] text-center">
                {Math.round(imageZoom * 100)}%
              </span>
              <Button
                variant="ghost"
                size="icon"
                onClick={(e) => {
                  e.stopPropagation();
                  setImageZoom((z) => Math.min(3, z + 0.25));
                }}
                className="p-2 hover:bg-white/20 text-white"
              >
                <ZoomIn className="w-5 h-5" />
              </Button>
              <div className="w-px h-6 bg-white/30 mx-1"></div>
              <a
                href={viewingImage.imageUrl}
                download={`${viewingImage.title}.png`}
                onClick={(e) => e.stopPropagation()}
                className="p-2 hover:bg-white/20 rounded-full text-white transition-colors"
              >
                <Download className="w-5 h-5" />
              </a>
            </div>

            {/* Image info */}
            <div className="absolute top-4 left-4 max-w-md z-10">
              <h3 className="text-white font-bold text-lg">{viewingImage.title}</h3>
              <p className="text-white/70 text-sm mt-1">{viewingImage.prompt}</p>
              <p className="text-white/50 text-xs mt-2">
                {viewingImage.style} ΓÇó {formatDate(viewingImage.savedAt)}
              </p>
            </div>

            {/* Image */}
            <div
              className="max-w-[90vw] max-h-[80vh] overflow-auto"
              onClick={(e) => e.stopPropagation()}
            >
              <img
                src={viewingImage.imageUrl}
                alt={viewingImage.title}
                className="rounded-lg transition-transform duration-300"
                style={{ transform: `scale(${imageZoom})`, transformOrigin: 'center' }}
              />
