// Translation cache
const translationCache = new Map<SupportedLanguage, TranslationKeys>();
translationCache.set('en', defaultTranslations);

interface I18nContextValue {
  language: SupportedLanguage;
  direction: 'ltr' | 'rtl';
  setLanguage: (lang: SupportedLanguage) => void;
  t: (key: string, params?: Record<string, string | number>) => string;
  isLoading: boolean;
}

const I18nContext = createContext<I18nContextValue | null>(null);

// Helper to get nested value from object using dot notation
function getNestedValue(obj: any, path: string): string | undefined {
  return path.split('.').reduce((current, key) => current?.[key], obj);
}

// Dynamic translation loader (loads from public/locales)
async function loadTranslations(language: SupportedLanguage): Promise<TranslationKeys> {
  if (translationCache.has(language)) {
    return translationCache.get(language)!;
  }

  try {
    const response = await fetch(`/locales/${language}.json`);
    if (response.ok) {
      const translations = await response.json();
      // Merge with defaults to ensure all keys exist
      const merged = deepMerge(defaultTranslations, translations);
      translationCache.set(language, merged);
      return merged;
    }
  } catch (error) {
    console.warn(`Failed to load translations for ${language}, falling back to English`);
  }

  return defaultTranslations;
}

// Deep merge helper
function deepMerge<T extends Record<string, unknown>>(target: T, source: DeepPartial<T>): T {
  const result = { ...target } as Record<string, unknown>;

  for (const key in source) {
    if (source[key] !== undefined) {
      if (typeof source[key] === 'object' && !Array.isArray(source[key])) {
        result[key] = deepMerge((result[key] || {}) as Record<string, unknown>, source[key] as DeepPartial<Record<string, unknown>>);
      } else {
        result[key] = source[key];
      }
    }
  }

  return result as T;
}

export function I18nProvider({ children }: { children: ReactNode }) {
  const [language, setLanguageState] = useState<SupportedLanguage>('en');
  const [translations, setTranslations] = useState<TranslationKeys>(defaultTranslations);
  const [isLoading, setIsLoading] = useState(false);

  const languageInfo =
    SUPPORTED_LANGUAGES.find((l) => l.code === language) || SUPPORTED_LANGUAGES[0];

  useEffect(() => {
    // Load saved language preference
    const saved = localStorage.getItem('genesis-language') as SupportedLanguage | null;
    if (saved && SUPPORTED_LANGUAGES.some((l) => l.code === saved)) {
      setLanguageState(saved);
    } else {
      // Detect browser language
      const browserLang = navigator.language.split('-')[0] as SupportedLanguage;
      if (SUPPORTED_LANGUAGES.some((l) => l.code === browserLang)) {
        setLanguageState(browserLang);
      }
    }
  }, []);

  useEffect(() => {
    // Load translations when language changes
    setIsLoading(true);
    loadTranslations(language)
      .then(setTranslations)
      .finally(() => setIsLoading(false));

    // Update document direction
    document.documentElement.dir = languageInfo.direction;
    document.documentElement.lang = language;
  }, [language, languageInfo.direction]);

  const setLanguage = (lang: SupportedLanguage) => {
    setLanguageState(lang);
    localStorage.setItem('genesis-language', lang);
  };

  const t = (key: string, params?: Record<string, string | number>): string => {
    let value =
      getNestedValue(translations, key) || getNestedValue(defaultTranslations, key) || key;

    // Replace parameters {param}
    if (params) {
      Object.entries(params).forEach(([param, val]) => {
        value = value.replace(`{${param}}`, String(val));
      });
    }

    return value;
  };

  return (
    <I18nContext.Provider
      value={{
        language,
        direction: languageInfo.direction,
        setLanguage,
        t,
        isLoading,
      }}
    >
      {children}
    </I18nContext.Provider>
  );
}

export function useI18n() {
  const context = useContext(I18nContext);
  if (!context) {
    throw new Error('useI18n must be used within an I18nProvider');
  }
  return context;
}

// Utility hook for RTL support
export function useRTL() {
  const { direction } = useI18n();
  return {
    isRTL: direction === 'rtl',
    startAlign: direction === 'rtl' ? 'right' : 'left',
    endAlign: direction === 'rtl' ? 'left' : 'right',
    marginStart: direction === 'rtl' ? 'marginRight' : 'marginLeft',
    marginEnd: direction === 'rtl' ? 'marginLeft' : 'marginRight',
    paddingStart: direction === 'rtl' ? 'paddingRight' : 'paddingLeft',
    paddingEnd: direction === 'rtl' ? 'paddingLeft' : 'paddingRight',
  };
}

/**
 * Mars-Class Infrastructure Context
 *
 * React context provider for Mars-Class infrastructure services.
 * Initializes all services on mount and provides access via hooks.
 *
 * Usage:
 * ```tsx
 * // In App.tsx or main entry
 * import { InfrastructureProvider } from '@/contexts/InfrastructureContext';
 *
 * function App() {
 *   return (
 *     <InfrastructureProvider>
 *       <YourApp />
 *     </InfrastructureProvider>
 *   );
 * }
 *
 * // In any component
 * import { useInfrastructureContext } from '@/contexts/InfrastructureContext';
 *
 * function MyComponent() {
 *   const { isReady, health, services } = useInfrastructureContext();
 *
 *   if (!isReady) return <LoadingSpinner />;
 *
 *   // Use services...
 * }
 * ```
 */

import type React from 'react';
import { Button } from '../components/ui/button';
import {
  type ReactNode,
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useState,
} from 'react';

import {
  type BootstrapProgress,
  type InfrastructureHealthCheck,
  type InfrastructureServices,
  bootstrapInfrastructure,
  checkInfrastructureHealth,
  getInfrastructureOrNull,
  isInfrastructureReady,
  shutdownInfrastructure,
} from '../services/infrastructure/bootstrap';

// ============================================================================
// TYPES
// ============================================================================

export interface InfrastructureContextValue {
  // State
  isReady: boolean;
  isInitializing: boolean;
  error: Error | null;
  progress: BootstrapProgress | null;

  // Services (null if not ready)
  services: InfrastructureServices | null;

  // Health
  health: InfrastructureHealthCheck | null;
  refreshHealth: () => Promise<void>;

  // Actions
  reinitialize: () => Promise<void>;
}

export interface InfrastructureProviderProps {
  children: ReactNode;

  /**
   * Options for infrastructure initialization
   */
  options?: {
    /** Skip configuration validation (useful for testing) */
    skipValidation?: boolean;

    /** Enable/disable specific services */
    services?: {
      cache?: boolean;
      storage?: boolean;
      jobs?: boolean;
      tracing?: boolean;
    };

    /** Health check interval in ms (0 to disable) */
    healthCheckInterval?: number;
  };

  /**
   * Loading component shown during initialization
   */
  loadingComponent?: ReactNode;

  /**
   * Error component shown if initialization fails
   */
  errorComponent?: (error: Error, retry: () => void) => ReactNode;

  /**
   * Called when initialization completes
   */
  onReady?: (services: InfrastructureServices) => void;

  /**
   * Called if initialization fails
   */
  onError?: (error: Error) => void;
}

// ============================================================================
// CONTEXT
// ============================================================================

const InfrastructureContext = createContext<InfrastructureContextValue | null>(null);

// ============================================================================
// PROVIDER
// ============================================================================

export function InfrastructureProvider({
  children,
  options = {},
  loadingComponent,
  errorComponent,
  onReady,
  onError,
}: InfrastructureProviderProps) {
  const [isReady, setIsReady] = useState(isInfrastructureReady());
  const [isInitializing, setIsInitializing] = useState(false);
  const [error, setError] = useState<Error | null>(null);
  const [progress, setProgress] = useState<BootstrapProgress | null>(null);
  const [services, setServices] = useState<InfrastructureServices | null>(
    getInfrastructureOrNull()
  );
  const [health, setHealth] = useState<InfrastructureHealthCheck | null>(null);

  const healthCheckInterval = options.healthCheckInterval ?? 60000; // 1 minute default

  // Initialize infrastructure
  const initialize = useCallback(async () => {
    if (isReady || isInitializing) return;

    setIsInitializing(true);
    setError(null);

    try {
      const result = await bootstrapInfrastructure(
        {
          skipValidation: options.skipValidation,
          services: options.services,
        },
        (p) => setProgress(p)
      );

      setServices(result);
      setIsReady(true);
      onReady?.(result);

      // Initial health check
      const healthResult = await checkInfrastructureHealth();
      setHealth(healthResult);
    } catch (err) {
      const error = err instanceof Error ? err : new Error(String(err));
      setError(error);
      onError?.(error);
    } finally {
      setIsInitializing(false);
    }
  }, [isReady, isInitializing, options, onReady, onError]);

  // Reinitialize (e.g., after error)
  const reinitialize = useCallback(async () => {
    setIsReady(false);
    setServices(null);
    await shutdownInfrastructure();
    await initialize();
  }, [initialize]);

  // Refresh health check
  const refreshHealth = useCallback(async () => {
    if (!isReady) return;

    try {
      const result = await checkInfrastructureHealth();
      setHealth(result);
    } catch (err) {
      console.error('[InfrastructureContext] Health check failed:', err);
    }
  }, [isReady]);

  // Initialize on mount
  useEffect(() => {
    initialize();

    return () => {
      // Shutdown on unmount
      shutdownInfrastructure().catch(console.error);
    };
  }, [initialize]);

  // Periodic health checks
  useEffect(() => {
    if (!isReady || healthCheckInterval === 0) return;

    const interval = setInterval(refreshHealth, healthCheckInterval);
    return () => clearInterval(interval);
  }, [isReady, healthCheckInterval, refreshHealth]);

  // Context value
  const value = useMemo<InfrastructureContextValue>(
    () => ({
      isReady,
      isInitializing,
      error,
      progress,
      services,
      health,
      refreshHealth,
      reinitialize,
    }),
    [isReady, isInitializing, error, progress, services, health, refreshHealth, reinitialize]
  );

  // Render loading state
  if (isInitializing && !isReady) {
    return loadingComponent ? (
      <>{loadingComponent}</>
    ) : (
      <div className="flex items-center justify-center min-h-screen">
        <div className="text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary mx-auto mb-4" />
          <p className="text-muted-foreground">
            {progress?.message ?? 'Initializing infrastructure...'}
          </p>
          {progress && (
            <div className="w-48 bg-muted rounded-full h-2 mt-2 mx-auto overflow-hidden">
              <div
                className="bg-primary h-2 rounded-full transition-all"
                data-progress={progress.progress}
              />
            </div>
          )}
        </div>
      </div>
    );
  }

  // Render error state
  if (error && !isReady) {
    return errorComponent ? (
      <>{errorComponent(error, reinitialize)}</>
    ) : (
      <div className="flex items-center justify-center min-h-screen">
        <div className="text-center max-w-md mx-auto p-6">
          <div className="text-destructive text-5xl mb-4">ΓÜá∩╕Å</div>
          <h2 className="text-xl font-semibold mb-2">Initialization Failed</h2>
          <p className="text-muted-foreground mb-4">{error.message}</p>
          <Button
            variant="default"
            onClick={reinitialize}
            className="hover:opacity-90"
          >
            Retry
          </Button>
        </div>
      </div>
    );
  }

  return <InfrastructureContext.Provider value={value}>{children}</InfrastructureContext.Provider>;
}

// ============================================================================
// HOOK
// ============================================================================

/**
 * Access infrastructure context.
 * Must be used within InfrastructureProvider.
 */
export function useInfrastructureContext(): InfrastructureContextValue {
  const context = useContext(InfrastructureContext);

  if (!context) {
    throw new Error('useInfrastructureContext must be used within InfrastructureProvider');
  }

  return context;
}

/**
 * Check if infrastructure is ready without throwing.
 * Useful for conditional rendering.
 */
export function useInfrastructureReady(): boolean {
  const context = useContext(InfrastructureContext);
  return context?.isReady ?? false;
}

/**
 * Get infrastructure services or null if not ready.
 */
export function useInfrastructureServices(): InfrastructureServices | null {
  const context = useContext(InfrastructureContext);
  return context?.services ?? null;
}

// ============================================================================
// HOC
// ============================================================================

/**
 * Higher-order component that ensures infrastructure is ready before rendering.
 */
export function withInfrastructure<P extends object>(
  Component: React.ComponentType<P & { infrastructure: InfrastructureServices }>
): React.FC<P> {
  return function WithInfrastructure(props: P) {
    const { isReady, services } = useInfrastructureContext();

    if (!isReady || !services) {
      return (
        <div className="flex items-center justify-center p-8">
          <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary" />
        </div>
      );
    }

    return <Component {...props} infrastructure={services} />;
  };
}

// ============================================================================
// EXPORTS
// ============================================================================

export { InfrastructureContext };

/**
 * Integrations Context - React Provider for All Services
 *
 * Provides centralized access to all integration services with:
 * - Automatic initialization on mount
 * - User context synchronization
 * - Health monitoring
 * - Error boundaries
 *
 * @example
 * ```tsx
 * // In your app root
 * <IntegrationsProvider user={user}>
 *   <App />
 * </IntegrationsProvider>
 *
 * // In any component
 * const { isReady, health, sentry, upstash } = useIntegrationsContext();
 * ```
 */

import type React from 'react';
import {
  type ReactNode,
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useState,
} from 'react';

import {
  type BootstrapResult,
  type IntegrationConfig,
  type IntegrationHealth,
  bootstrapIntegrations,
  clearIntegrationUser,
  getIntegrationHealth,
  isIntegrationsReady,
  updateIntegrationUser,
} from '../services/integrations/bootstrap';

import { arcjet } from '../services/integrations/arcjet';
import { checkly } from '../services/integrations/checkly';
import { hyperdx } from '../services/integrations/hyperdx';
import { sentry } from '../services/integrations/sentry';
import {
  FEATURE_FLAGS,
  type FeatureFlagName,
  type StatsigUser,
  statsig,
} from '../services/integrations/statsig';
import { type UpstashRedis, getUpstashOrNull } from '../services/integrations/upstash';

// ============================================================================
// TYPES
// ============================================================================

export interface IntegrationsContextValue {
  // Status
  isReady: boolean;
  isInitializing: boolean;
  error: Error | null;
  health: IntegrationHealth | null;
  result: BootstrapResult | null;

  // Services
  sentry: typeof sentry;
  statsig: typeof statsig;
  hyperdx: typeof hyperdx;
  upstash: UpstashRedis | null;
  checkly: typeof checkly;
  arcjet: typeof arcjet;

  // Methods
  checkFeature: (flag: FeatureFlagName) => boolean;
  refreshHealth: () => Promise<void>;
  updateUser: (user: StatsigUser) => Promise<void>;
  clearUser: () => Promise<void>;
}

export interface IntegrationsProviderProps {
  children: ReactNode;

  /**
   * Initial user for feature flags and error tracking
   */
  user?: StatsigUser;

  /**
   * Configuration overrides
   */
  config?: IntegrationConfig;

  /**
   * Component to show while initializing
   */
  loadingComponent?: ReactNode;

  /**
   * Component to show on initialization error
   */
  errorComponent?: (error: Error, retry: () => void) => ReactNode;

  /**
   * Callback when ready
   */
  onReady?: (result: BootstrapResult) => void;

  /**
   * Callback on error
   */
  onError?: (error: Error) => void;
}

// ============================================================================
// CONTEXT
// ============================================================================

const IntegrationsContext = createContext<IntegrationsContextValue | null>(null);

// ============================================================================
// PROVIDER
// ============================================================================

export function IntegrationsProvider({
  children,
  user,
  config,
  loadingComponent,
  errorComponent,
  onReady,
  onError,
}: IntegrationsProviderProps): React.ReactElement {
  const [isReady, setIsReady] = useState(isIntegrationsReady());
  const [isInitializing, setIsInitializing] = useState(!isIntegrationsReady());
  const [error, setError] = useState<Error | null>(null);
  const [health, setHealth] = useState<IntegrationHealth | null>(null);
  const [result, setResult] = useState<BootstrapResult | null>(null);

  // Feature flag cache for synchronous access
  const [flagCache, setFlagCache] = useState<Map<string, boolean>>(new Map());

  // Initialize on mount
  useEffect(() => {
    if (isReady) return;

    let cancelled = false;

    async function init() {
      try {
        const bootstrapResult = await bootstrapIntegrations(config, user);

        if (cancelled) return;

        setResult(bootstrapResult);
        setIsReady(true);
        setIsInitializing(false);

        // Pre-fetch common feature flags
        const flagNames = Object.values(FEATURE_FLAGS) as string[];
        const flags = await Promise.all(
          flagNames.map(async (flag) => ({
            flag,
            value: await statsig.checkGate(flag as FeatureFlagName),
          }))
        );

        const newCache = new Map<string, boolean>();
        flags.forEach(({ flag, value }) => newCache.set(flag, value));
        setFlagCache(newCache);

        // Get initial health
        const initialHealth = await getIntegrationHealth();
        setHealth(initialHealth);

        onReady?.(bootstrapResult);
      } catch (err) {
        if (cancelled) return;

        const error = err instanceof Error ? err : new Error(String(err));
        setError(error);
        setIsInitializing(false);
        onError?.(error);
      }
    }

    init();

    return () => {
      cancelled = true;
    };
  }, [config, user, isReady, onReady, onError]);

  // Update user when it changes
  useEffect(() => {
    if (!isReady || !user) return;

    updateIntegrationUser(user);
  }, [isReady, user]);

  // Health check interval
  useEffect(() => {
    if (!isReady) return;

    const interval = setInterval(async () => {
      const newHealth = await getIntegrationHealth();
      setHealth(newHealth);
    }, 60000);

    return () => clearInterval(interval);
  }, [isReady]);

  // Cleanup on unmount
  useEffect(() => {
    return () => {
      // Don't shutdown on unmount - other parts of the app may still need services
      // shutdownIntegrations();
    };
  }, []);

  // Methods
  const checkFeature = useCallback(
    (flag: FeatureFlagName): boolean => {
      return flagCache.get(flag) ?? false;
    },
    [flagCache]
  );

  const refreshHealth = useCallback(async () => {
    const newHealth = await getIntegrationHealth();
    setHealth(newHealth);
  }, []);

  const updateUser = useCallback(async (newUser: StatsigUser) => {
    await updateIntegrationUser(newUser);
  }, []);

  const clearUser = useCallback(async () => {
    await clearIntegrationUser();
  }, []);

  const retry = useCallback(() => {
    setError(null);
    setIsInitializing(true);
    setIsReady(false);
  }, []);

  // Context value
  const contextValue = useMemo<IntegrationsContextValue>(
    () => ({
      isReady,
      isInitializing,
      error,
      health,
      result,
      sentry,
      statsig,
      hyperdx,
      upstash: getUpstashOrNull(),
      checkly,
      arcjet,
      checkFeature,
      refreshHealth,
      updateUser,
      clearUser,
    }),
    [
      isReady,
      isInitializing,
      error,
      health,
      result,
      checkFeature,
      refreshHealth,
      updateUser,
      clearUser,
    ]
  );

  // Render states
  if (error && errorComponent) {
    return <>{errorComponent(error, retry)}</>;
  }

  if (isInitializing && loadingComponent) {
    return <>{loadingComponent}</>;
  }

  return (
    <IntegrationsContext.Provider value={contextValue}>{children}</IntegrationsContext.Provider>
  );
}

// ============================================================================
// HOOK
// ============================================================================

/**
 * Access integrations context
 */
export function useIntegrationsContext(): IntegrationsContextValue {
  const context = useContext(IntegrationsContext);

  if (!context) {
    throw new Error('useIntegrationsContext must be used within IntegrationsProvider');
  }

  return context;
}

/**
 * Check if integrations are ready (safe to use outside provider)
 */
export function useIntegrationsReady(): boolean {
  const context = useContext(IntegrationsContext);
  return context?.isReady ?? false;
}

/**
 * Get integration health (safe to use outside provider)
 */
export function useIntegrationsHealth(): IntegrationHealth | null {
  const context = useContext(IntegrationsContext);
  return context?.health ?? null;
}

// ============================================================================
// HOC
// ============================================================================

/**
 * Higher-order component to require integrations
 */
export function withIntegrations<P extends object>(
  Component: React.ComponentType<P & { integrations: IntegrationsContextValue }>
): React.ComponentType<P> {
  return function WithIntegrations(props: P) {
    const integrations = useIntegrationsContext();
    return <Component {...props} integrations={integrations} />;
  };
}

/**
 * Higher-order component to require a feature flag
 */
export function withFeatureFlag<P extends object>(
  Component: React.ComponentType<P>,
  flag: FeatureFlagName,
  Fallback?: React.ComponentType<P>
): React.ComponentType<P> {
  return function WithFeatureFlag(props: P) {
    const { checkFeature, isReady } = useIntegrationsContext();

    if (!isReady) {
      return null;
    }

    if (!checkFeature(flag)) {
      return Fallback ? <Fallback {...props} /> : null;
    }

    return <Component {...props} />;
  };
}

export default IntegrationsProvider;

import type React from 'react';
import { createContext, useContext, useEffect, useState } from 'react';
import { defaultTheme, themes } from '../config/themes';
import type { Theme, ThemeId } from '../types/theme';

interface ThemeContextType {
  currentTheme: Theme;
  setTheme: (themeId: ThemeId) => void;
  availableThemes: Theme[];
}

export const ThemeContext = createContext<ThemeContextType | undefined>(undefined);

export const useTheme = () => {
  const context = useContext(ThemeContext);
  if (context === undefined) {
    throw new Error('useTheme must be used within a ThemeProvider');
  }
  return context;
};

export const ThemeProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [currentTheme, setCurrentTheme] = useState<Theme>(() => {
    const savedThemeId = localStorage.getItem('genesis_theme_id');
    return themes.find((t) => t.id === savedThemeId) || defaultTheme;
  });

  useEffect(() => {
    const root = document.documentElement;
    const body = document.body;

    // Add smooth transition
    root.style.setProperty('transition', 'background-color 0.3s ease, color 0.3s ease');

    // Apply CSS variables
    Object.entries(currentTheme.cssVariables).forEach(([key, value]) => {
      root.style.setProperty(key, value);
    });

    // Add theme class to body for conditional styling
    body.className = body.className.replace(/theme-\w+/g, '');
    body.classList.add(`theme-${currentTheme.id}`);

    // Save to localStorage
    localStorage.setItem('genesis_theme_id', currentTheme.id);

    // Dispatch custom event to notify other components
    window.dispatchEvent(new CustomEvent('themeChanged', { detail: { theme: currentTheme } }));
  }, [currentTheme]);

  const setTheme = (themeId: ThemeId) => {
    const theme = themes.find((t) => t.id === themeId);
    if (theme) {
      setCurrentTheme(theme);
    }
  };

  return (
    <ThemeContext.Provider value={{ currentTheme, setTheme, availableThemes: themes }}>
      {children}
    </ThemeContext.Provider>
  );
};

import { useCallback, useEffect, useRef, useState } from 'react';

interface AutoSaveOptions<T> {
  key: string;
  data: T;
  interval?: number; // in milliseconds
  enabled?: boolean;
  onSave?: (data: T) => void;
  onRestore?: (data: T) => void;
  debounceMs?: number;
}

interface AutoSaveState {
  lastSaved: Date | null;
  isSaving: boolean;
  hasUnsavedChanges: boolean;
  error: string | null;
}

interface UseAutoSaveReturn<T> {
  state: AutoSaveState;
  save: () => void;
  restore: () => T | null;
  clear: () => void;
  hasDraft: boolean;
}

export function useAutoSave<T>({
  key,
  data,
  interval = 30000, // 30 seconds default
  enabled = true,
  onSave,
  onRestore,
  debounceMs = 1000,
}: AutoSaveOptions<T>): UseAutoSaveReturn<T> {
  const [state, setState] = useState<AutoSaveState>({
    lastSaved: null,
    isSaving: false,
    hasUnsavedChanges: false,
    error: null,
  });

  const dataRef = useRef(data);
  const lastSavedDataRef = useRef<string | null>(null);
  const debounceTimerRef = useRef<NodeJS.Timeout | null>(null);
  const intervalRef = useRef<NodeJS.Timeout | null>(null);

  // Update ref when data changes
  useEffect(() => {
    dataRef.current = data;

    // Check if data has changed from last save
    const currentDataStr = JSON.stringify(data);
    if (lastSavedDataRef.current && lastSavedDataRef.current !== currentDataStr) {
      setState((prev) => ({ ...prev, hasUnsavedChanges: true }));
    }
  }, [data]);

  // Storage key with prefix
  const storageKey = `genesis_autosave_${key}`;

  // Save function
  const save = useCallback(() => {
    if (!enabled) return;

    setState((prev) => ({ ...prev, isSaving: true, error: null }));

    try {
      const dataToSave = {
        data: dataRef.current,
        timestamp: new Date().toISOString(),
        version: 1,
      };

      localStorage.setItem(storageKey, JSON.stringify(dataToSave));
      lastSavedDataRef.current = JSON.stringify(dataRef.current);

      setState({
        lastSaved: new Date(),
        isSaving: false,
        hasUnsavedChanges: false,
        error: null,
      });

      onSave?.(dataRef.current);
    } catch (error) {
      setState((prev) => ({
        ...prev,
        isSaving: false,
        error: error instanceof Error ? error.message : 'Failed to save',
      }));
    }
  }, [enabled, storageKey, onSave]);

  // Debounced save (for manual triggering on changes)
  const debouncedSave = useCallback(() => {
    if (debounceTimerRef.current) {
      clearTimeout(debounceTimerRef.current);
    }

    debounceTimerRef.current = setTimeout(save, debounceMs);
  }, [save, debounceMs]);

  // Restore function
  const restore = useCallback((): T | null => {
    try {
      const saved = localStorage.getItem(storageKey);
      if (!saved) return null;

      const parsed = JSON.parse(saved);
      const restoredData = parsed.data as T;

      lastSavedDataRef.current = JSON.stringify(restoredData);
      setState((prev) => ({
        ...prev,
        lastSaved: new Date(parsed.timestamp),
        hasUnsavedChanges: false,
      }));

      onRestore?.(restoredData);
      return restoredData;
    } catch (error) {
      console.error('Failed to restore autosave:', error);
      return null;
    }
  }, [storageKey, onRestore]);

  // Clear saved data
  const clear = useCallback(() => {
    try {
      localStorage.removeItem(storageKey);
      lastSavedDataRef.current = null;
      setState({
        lastSaved: null,
        isSaving: false,
        hasUnsavedChanges: false,
        error: null,
      });
    } catch (error) {
      console.error('Failed to clear autosave:', error);
    }
  }, [storageKey]);

  // Check if draft exists
  const hasDraft = (() => {
    try {
      return localStorage.getItem(storageKey) !== null;
    } catch {
      return false;
    }
  })();

  // Set up auto-save interval
  useEffect(() => {
    if (!enabled || interval <= 0) return;

    intervalRef.current = setInterval(() => {
      if (state.hasUnsavedChanges) {
        save();
      }
    }, interval);

    return () => {
      if (intervalRef.current) {
        clearInterval(intervalRef.current);
      }
    };
  }, [enabled, interval, save, state.hasUnsavedChanges]);

  // Cleanup debounce timer on unmount
  useEffect(() => {
    return () => {
      if (debounceTimerRef.current) {
        clearTimeout(debounceTimerRef.current);
      }
    };
  }, []);

  // Save before page unload if there are unsaved changes
  useEffect(() => {
    const handleBeforeUnload = (e: BeforeUnloadEvent) => {
      if (state.hasUnsavedChanges && enabled) {
        save();
        e.preventDefault();
        e.returnValue = 'You have unsaved changes. Are you sure you want to leave?';
      }
    };

    window.addEventListener('beforeunload', handleBeforeUnload);
    return () => window.removeEventListener('beforeunload', handleBeforeUnload);
  }, [state.hasUnsavedChanges, enabled, save]);

  return {
    state,
    save: debouncedSave,
    restore,
    clear,
    hasDraft,
  };
}

import { AnimatePresence, motion } from 'framer-motion';
import { AlertCircle, Check, Cloud, CloudOff, Loader } from 'lucide-react';
// Auto-save indicator component
import type React from 'react';
import { Button } from '../components/ui/button';

interface AutoSaveIndicatorProps {
  state: AutoSaveState;
  className?: string;
}

export const AutoSaveIndicator: React.FC<AutoSaveIndicatorProps> = ({ state, className = '' }) => {
  const getStatusIcon = () => {
    if (state.error) {
      return <AlertCircle className="w-4 h-4 text-red-500" />;
    }
    if (state.isSaving) {
      return (
        <motion.div
          animate={{ rotate: 360 }}
          transition={{ repeat: Number.POSITIVE_INFINITY, duration: 1 }}
        >
          <Loader className="w-4 h-4 text-blue-500" />
        </motion.div>
      );
    }
    if (state.hasUnsavedChanges) {
      return <Cloud className="w-4 h-4 text-yellow-500" />;
    }
    if (state.lastSaved) {
      return <Check className="w-4 h-4 text-green-500" />;
    }
    return <CloudOff className="w-4 h-4 text-gray-400" />;
  };

  const getStatusText = () => {
    if (state.error) {
      return `Error: ${state.error}`;
    }
    if (state.isSaving) {
      return 'Saving...';
    }
    if (state.hasUnsavedChanges) {
      return 'Unsaved changes';
    }
    if (state.lastSaved) {
      return `Saved ${formatTimeAgo(state.lastSaved)}`;
    }
    return 'Not saved';
  };

  return (
    <AnimatePresence mode="wait">
      <motion.div
        key={getStatusText()}
        initial={{ opacity: 0, y: -10 }}
        animate={{ opacity: 1, y: 0 }}
        exit={{ opacity: 0, y: 10 }}
        className={`flex items-center gap-2 text-xs text-gray-500 dark:text-gray-400 ${className}`}
      >
        {getStatusIcon()}
        <span>{getStatusText()}</span>
      </motion.div>
    </AnimatePresence>
  );
};

