import { useCallback, useEffect, useRef, useState } from 'react';
import { useAuth } from '../contexts/AuthContext';

/**
 * Google One Tap Hook
 *
 * Automatically shows Google One Tap prompt when:
 * - User is not authenticated
 * - User has previously signed in with Google
 *
 * This provides seamless "Continue as..." authentication
 *
 * FedCM is enabled for production and disabled for localhost
 *
 * IMPORTANT: Uses nonce for security as per Supabase documentation:
 * - Hashed nonce (SHA-256) is sent to Google
 * - Original nonce is sent to Supabase signInWithIdToken
 */

/**
 * Generate a cryptographically secure nonce and its SHA-256 hash
 * The hashed version goes to Google, the original goes to Supabase
 */
const generateNonce = async (): Promise<[string, string]> => {
  // Generate random bytes and convert to base64
  const nonce = btoa(String.fromCharCode(...crypto.getRandomValues(new Uint8Array(32))));

  // Hash the nonce using SHA-256
  const encoder = new TextEncoder();
  const encodedNonce = encoder.encode(nonce);
  const hashBuffer = await crypto.subtle.digest('SHA-256', encodedNonce);
  const hashArray = Array.from(new Uint8Array(hashBuffer));
  const hashedNonce = hashArray.map((b) => b.toString(16).padStart(2, '0')).join('');

  console.warn('[GoogleOneTap] Generated nonce (length):', nonce.length);
  console.warn('[GoogleOneTap] Hashed nonce (for Google):', hashedNonce.substring(0, 20) + '...');

  return [nonce, hashedNonce];
};

export const useGoogleOneTap = () => {
  const { user, signInWithIdToken, loading } = useAuth();

  // Store the original nonce so the callback can access it
  const nonceRef = useRef<string | null>(null);
  const [isInitialized, setIsInitialized] = useState(false);

  // Define callback with useCallback to maintain stable reference
  const handleCredentialResponse = useCallback(
    async (response: any) => {
      console.warn('[GoogleOneTap] Credential received, processing...');
      console.warn('[GoogleOneTap] Response object:', JSON.stringify(response, null, 2));

      if (!response?.credential) {
        console.error('[GoogleOneTap] No credential in response:', response);
        return;
      }

      // Decode JWT to see the payload (for debugging)
      try {
        const payloadBase64 = response.credential.split('.')[1];
        const payload = JSON.parse(atob(payloadBase64));
        console.warn('[GoogleOneTap] Token payload (decoded):', {
          email: payload.email,
          name: payload.name,
          iss: payload.iss,
          aud: payload.aud,
          nonce: payload.nonce ? 'present' : 'missing',
          exp: new Date(payload.exp * 1000).toISOString(),
        });
      } catch (e) {
        console.warn('[GoogleOneTap] Could not decode token for debugging');
      }

      // Get the original nonce that we stored
      const originalNonce = nonceRef.current;
      console.warn('[GoogleOneTap] Original nonce available:', !!originalNonce);

      try {
        console.warn('[GoogleOneTap] Calling signInWithIdToken with nonce...');
        const { data, error } = await signInWithIdToken(response.credential, originalNonce);

        if (error) {
          console.error('[GoogleOneTap] Sign-in error:', error);
          console.error('[GoogleOneTap] Error details:', {
            message: error.message,
            status: error.status,
            name: error.name,
            code: error.code,
          });

          // Log the error for debugging but don't show intrusive alerts
          // Users can still sign in using the regular button
          if (
            error.message?.includes('Invalid API key') ||
            error.message?.includes('401') ||
            error.message?.includes('Unauthorized')
          ) {
            console.error(
              '[GoogleOneTap] CONFIGURATION ERROR: The Google Client ID is not configured in Supabase.\n' +
                'To fix this:\n' +
                '1. Go to Supabase Dashboard ΓåÆ Authentication ΓåÆ Providers ΓåÆ Google\n' +
                '2. Add your Google Web Client ID to the "Client IDs" field (NOT the OAuth Client ID/Secret fields)\n' +
                '3. Make sure VITE_GOOGLE_CLIENT_ID in your .env matches this Client ID\n' +
                '4. Ensure the Client ID format is: xxxxxxxx.apps.googleusercontent.com'
            );
          }

          if (error.message?.includes('provider is not enabled')) {
            console.error('[GoogleOneTap] Google provider is not enabled in Supabase Dashboard!');
          }

          if (error.message?.includes('nonce')) {
            console.error(
              '[GoogleOneTap] Nonce mismatch - this can happen if the page was refreshed between prompt display and sign-in'
            );
          }

          // Silently fail - One Tap is optional, users can use regular sign-in
          return;
        }

        if (data?.user) {
          console.warn('[GoogleOneTap] Sign-in successful! User:', data.user.email);
          console.warn('[GoogleOneTap] Session created:', !!data.session);
          // Force a page reload to ensure all components pick up the new auth state
          window.location.reload();
        } else {
          console.warn('[GoogleOneTap] Sign-in completed but no user data returned');
        }
      } catch (error: any) {
        console.error('[GoogleOneTap] Exception during sign-in:', error);
        console.error('[GoogleOneTap] Exception stack:', error.stack);
        // Silently fail - don't interrupt user experience
      }
    },
    [signInWithIdToken]
  );

  useEffect(() => {
    // Only show if user is not authenticated and auth is done loading
    if (loading) {
      console.warn('[GoogleOneTap] Auth still loading, waiting...');
      return;
    }

    if (user) {
      console.warn('[GoogleOneTap] User already authenticated, skipping prompt');
      // If user is authenticated, ensure any existing prompt is closed
      if (window.google?.accounts?.id) {
        window.google.accounts.id.cancel();
      }
      return;
    }

    console.warn('[GoogleOneTap] No user, preparing to show prompt...');

    // Determine if we're on localhost
    const isLocalhost =
      window.location.hostname === 'localhost' || window.location.hostname === '127.0.0.1';

    // Load Google One Tap script
    const script = document.createElement('script');
    script.src = 'https://accounts.google.com/gsi/client';
    script.async = true;
    script.defer = true;

    script.onload = async () => {
      // Initialize Google One Tap
      if (window.google) {
        const clientId = import.meta.env.VITE_GOOGLE_CLIENT_ID;
        console.warn(
          '[GoogleOneTap] Initializing with Client ID:',
          clientId ? `${clientId.substring(0, 20)}...` : 'UNDEFINED'
        );

        if (!clientId) {
          console.error('[GoogleOneTap] MISSING VITE_GOOGLE_CLIENT_ID in .env file');
          return;
        }

        try {
          // Generate nonce for security
          // Hashed nonce goes to Google, original nonce goes to Supabase
          const [originalNonce, hashedNonce] = await generateNonce();

          // Store the original nonce for the callback
          nonceRef.current = originalNonce;
          console.warn('[GoogleOneTap] Nonce stored for callback');

          window.google.accounts.id.initialize({
            client_id: clientId,
            callback: handleCredentialResponse,
            auto_select: true, // Auto-select if user previously signed in
            cancel_on_tap_outside: true, // Allow clicking outside to close
            // Enable FedCM for production, disable for localhost
            use_fedcm_for_prompt: !isLocalhost,
            // CRITICAL: Pass the HASHED nonce to Google
            nonce: hashedNonce,
            // Enable ITP support for Safari
            itp_support: true,
          });

          setIsInitialized(true);
          console.warn('[GoogleOneTap] Initialized with nonce, showing prompt...');

          // Display the One Tap prompt
          window.google.accounts.id.prompt((notification: any) => {
            console.warn('[GoogleOneTap] Prompt notification received');

            if (notification.isDisplayed && notification.isDisplayed()) {
              console.warn('[GoogleOneTap] Prompt is displayed');
            }
            if (notification.isNotDisplayed && notification.isNotDisplayed()) {
              const reason = notification.getNotDisplayedReason?.() || 'unknown';
              console.warn('[GoogleOneTap] Prompt not displayed, reason:', reason);
            }
            if (notification.isSkippedMoment && notification.isSkippedMoment()) {
              const reason = notification.getSkippedReason?.() || 'unknown';
              console.warn('[GoogleOneTap] Prompt skipped, reason:', reason);
            }
            if (notification.isDismissedMoment && notification.isDismissedMoment()) {
              const reason = notification.getDismissedReason?.() || 'unknown';
              console.warn('[GoogleOneTap] Prompt dismissed, reason:', reason);
            }
          });
        } catch (initError) {
          console.error('[GoogleOneTap] Initialization error:', initError);
        }
      } else {
        console.error('[GoogleOneTap] Google script loaded but window.google is undefined');
      }
    };

    script.onerror = (error) => {
      console.error('[GoogleOneTap] Failed to load Google script:', error);
    };

    document.body.appendChild(script);

    return () => {
      // Cleanup
      if (window.google?.accounts?.id) {
        window.google.accounts.id.cancel();
      }
      if (document.body.contains(script)) {
        document.body.removeChild(script);
      }
    };
  }, [user, loading, handleCredentialResponse]);
};

// Type declaration for Google One Tap
declare global {
  interface Window {
    google?: {
      accounts: {
        id: {
          initialize: (config: any) => void;
          prompt: (callback?: (notification: any) => void) => void;
          cancel: () => void;
        };
      };
    };
  }
}

import { useCallback, useEffect, useState } from 'react';

interface NetworkStatus {
  isOnline: boolean;
  isSlowConnection: boolean;
  connectionType: string | null;
  downlink: number | null;
  rtt: number | null;
  saveData: boolean;
}

export function useNetworkStatus(): NetworkStatus & {
  checkConnection: () => Promise<boolean>;
} {
  const [status, setStatus] = useState<NetworkStatus>(() => ({
    isOnline: typeof navigator !== 'undefined' ? navigator.onLine : true,
    isSlowConnection: false,
    connectionType: null,
    downlink: null,
    rtt: null,
    saveData: false,
  }));

  // Get connection info from Network Information API
  const getConnectionInfo = useCallback(() => {
    const connection =
      (navigator as unknown as Record<string, unknown>).connection ||
      (navigator as unknown as Record<string, unknown>).mozConnection ||
      (navigator as unknown as Record<string, unknown>).webkitConnection;

    if (connection) {
      return {
        connectionType: connection.effectiveType || connection.type || null,
        downlink: connection.downlink || null,
        rtt: connection.rtt || null,
        saveData: connection.saveData || false,
        isSlowConnection:
          connection.effectiveType === 'slow-2g' ||
          connection.effectiveType === '2g' ||
          (connection.rtt && connection.rtt > 500),
      };
    }
    return {
      connectionType: null,
      downlink: null,
      rtt: null,
      saveData: false,
      isSlowConnection: false,
    };
  }, []);

  // Ping server to verify actual connectivity
  const checkConnection = useCallback(async (): Promise<boolean> => {
    try {
      const controller = new AbortController();
      const timeoutId = setTimeout(() => controller.abort(), 5000);

      const response = await fetch('/api/health', {
        method: 'HEAD',
        cache: 'no-store',
        signal: controller.signal,
      });

      clearTimeout(timeoutId);
      return response.ok;
    } catch {
      // Fallback: try to fetch a small resource
      try {
        await fetch('/favicon.ico', {
          method: 'HEAD',
          cache: 'no-store',
        });
        return true;
      } catch {
        return false;
      }
    }
  }, []);

  useEffect(() => {
    const updateStatus = () => {
      const connectionInfo = getConnectionInfo();
      setStatus((prev) => ({
        ...prev,
        isOnline: navigator.onLine,
        ...connectionInfo,
      }));
    };

    // Listen for online/offline events
    window.addEventListener('online', updateStatus);
    window.addEventListener('offline', updateStatus);

    // Listen for connection changes
    const connection =
      (navigator as unknown as Record<string, unknown>).connection ||
      (navigator as unknown as Record<string, unknown>).mozConnection ||
      (navigator as unknown as Record<string, unknown>).webkitConnection;

    if (connection) {
      connection.addEventListener('change', updateStatus);
    }

    // Initial check
    updateStatus();

    return () => {
      window.removeEventListener('online', updateStatus);
      window.removeEventListener('offline', updateStatus);
      if (connection) {
        connection.removeEventListener('change', updateStatus);
      }
    };
  }, [getConnectionInfo]);

  return { ...status, checkConnection };
}

import { AnimatePresence, motion } from 'framer-motion';
import { AlertTriangle, RefreshCw, Wifi, WifiOff } from 'lucide-react';
// React component for offline indicator
import React from 'react';
import { Button } from '../components/ui/button';

interface OfflineIndicatorProps {
  position?: 'top' | 'bottom';
  showWhenOnline?: boolean;
}

export const OfflineIndicator: React.FC<OfflineIndicatorProps> = ({
  position = 'bottom',
  showWhenOnline = false,
}) => {
  const { isOnline, isSlowConnection, checkConnection } = useNetworkStatus();
  const [isChecking, setIsChecking] = React.useState(false);
  const [showOnlineMessage, setShowOnlineMessage] = React.useState(false);

  // Show "back online" message briefly when reconnecting
  useEffect(() => {
    if (isOnline && !showWhenOnline) {
      setShowOnlineMessage(true);
      const timer = setTimeout(() => setShowOnlineMessage(false), 3000);
      return () => clearTimeout(timer);
    }
  }, [isOnline, showWhenOnline]);

  const handleRetry = async () => {
    setIsChecking(true);
    await checkConnection();
    setIsChecking(false);
  };

  const positionClasses = position === 'top' ? 'top-0 left-0 right-0' : 'bottom-0 left-0 right-0';

  // Don't render if online and not showing online message
  if (isOnline && !showOnlineMessage && !isSlowConnection) {
    return null;
  }

  return (
    <AnimatePresence>
      <motion.div
        initial={{ y: position === 'top' ? -100 : 100, opacity: 0 }}
        animate={{ y: 0, opacity: 1 }}
        exit={{ y: position === 'top' ? -100 : 100, opacity: 0 }}
        className={`fixed ${positionClasses} z-[300] p-4 pointer-events-none`}
      >
        <div
          className={`
                    max-w-md mx-auto pointer-events-auto
                    ${
                      isOnline && showOnlineMessage
                        ? 'bg-green-500'
                        : isSlowConnection
                          ? 'bg-amber-500'
                          : 'bg-red-500'
                    }
                    text-white rounded-2xl
                    flex items-center gap-3 px-4 py-3
                `}
        >
          {isOnline && showOnlineMessage ? (
            <>
              <Wifi className="w-5 h-5" />
              <span className="flex-1 font-medium">Back online!</span>
            </>
          ) : isSlowConnection ? (
            <>
              <AlertTriangle className="w-5 h-5" />
              <span className="flex-1 font-medium">Slow connection detected</span>
            </>
          ) : (
            <>
              <WifiOff className="w-5 h-5" />
              <div className="flex-1">
                <p className="font-medium">You're offline</p>
                <p className="text-sm text-white/80">Some features may not be available</p>
              </div>
              <Button
                variant="ghost"
                size="icon"
                onClick={handleRetry}
                disabled={isChecking}
                title="Retry connection"
                className="bg-white/20 hover:bg-white/30"
              >
                <RefreshCw className={`w-5 h-5 ${isChecking ? 'animate-spin' : ''}`} />
              </Button>
            </>
          )}
        </div>
      </motion.div>
    </AnimatePresence>
  );
};

// Queue for offline actions
interface OfflineAction {
  id: string;
  type: string;
  payload: any;
  timestamp: number;
  retries: number;
}

const OFFLINE_QUEUE_KEY = 'genesis_offline_queue';

export function useOfflineQueue() {
  const [queue, setQueue] = useState<OfflineAction[]>(() => {
    try {
      const stored = localStorage.getItem(OFFLINE_QUEUE_KEY);
      return stored ? JSON.parse(stored) : [];
    } catch {
      return [];
    }
  });

  const { isOnline } = useNetworkStatus();

  // Save queue to localStorage
  useEffect(() => {
    localStorage.setItem(OFFLINE_QUEUE_KEY, JSON.stringify(queue));
  }, [queue]);

  // Add action to queue
  const addToQueue = useCallback((type: string, payload: any) => {
    const action: OfflineAction = {
      id: `${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
      type,
      payload,
      timestamp: Date.now(),
      retries: 0,
    };
    setQueue((prev) => [...prev, action]);
    return action.id;
  }, []);

  // Remove action from queue
  const removeFromQueue = useCallback((id: string) => {
    setQueue((prev) => prev.filter((action) => action.id !== id));
  }, []);

  // Process queue when back online
  const processQueue = useCallback(
    async (processor: (action: OfflineAction) => Promise<boolean>) => {
      if (!isOnline || queue.length === 0) return;

      for (const action of queue) {
        try {
          const success = await processor(action);
          if (success) {
            removeFromQueue(action.id);
          } else {
            // Increment retry count
            setQueue((prev) =>
              prev.map((a) => (a.id === action.id ? { ...a, retries: a.retries + 1 } : a))
            );
          }
        } catch (error) {
          console.error('[OfflineQueue] Failed to process action:', action, error);
        }
      }
    },
    [isOnline, queue, removeFromQueue]
  );

  // Clear old actions (older than 24 hours)
  useEffect(() => {
    const oneDayAgo = Date.now() - 24 * 60 * 60 * 1000;
    setQueue((prev) => prev.filter((action) => action.timestamp > oneDayAgo));
  }, []);

  return {
    queue,
    queueLength: queue.length,
    addToQueue,
    removeFromQueue,
    processQueue,
    clearQueue: () => setQueue([]),
  };
}

export default { useNetworkStatus, OfflineIndicator, useOfflineQueue };

import { useCallback, useEffect, useRef, useState } from 'react';
import type { SavedBook } from '../types';

/**
 * IndexedDB configuration
 */
const DB_NAME = 'GenesisOfflineDB';
const DB_VERSION = 1;
const STORE_BOOKS = 'books';
const STORE_SYNC_QUEUE = 'syncQueue';

interface SyncQueueItem {
  id: string;
  type: 'create' | 'update' | 'delete';
  data: SavedBook | string;
  timestamp: number;
  retries: number;
}

/**
 * Opens the IndexedDB database
 */
function openDatabase(): Promise<IDBDatabase> {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, DB_VERSION);

    request.onerror = () => reject(request.error);
    request.onsuccess = () => resolve(request.result);

    request.onupgradeneeded = (event) => {
      const db = (event.target as IDBOpenDBRequest).result;

      // Books store
      if (!db.objectStoreNames.contains(STORE_BOOKS)) {
        const booksStore = db.createObjectStore(STORE_BOOKS, { keyPath: 'id' });
        booksStore.createIndex('lastModified', 'lastModified', { unique: false });
        booksStore.createIndex('user_id', 'user_id', { unique: false });
      }

      // Sync queue store
      if (!db.objectStoreNames.contains(STORE_SYNC_QUEUE)) {
        const syncStore = db.createObjectStore(STORE_SYNC_QUEUE, { keyPath: 'id' });
        syncStore.createIndex('timestamp', 'timestamp', { unique: false });
      }
    };
  });
}

/**
 * Hook for offline-first data management
 */
export function useOfflineFirst<T extends { id: string }>(
  storeName: string,
  onlineSync?: (items: T[]) => Promise<void>,
  onlineFetch?: () => Promise<T[]>
) {
  const [isOnline, setIsOnline] = useState(navigator.onLine);
  const [isSyncing, setIsSyncing] = useState(false);
  const [pendingChanges, setPendingChanges] = useState(0);
  const [lastSyncTime, setLastSyncTime] = useState<Date | null>(null);
  const dbRef = useRef<IDBDatabase | null>(null);

  // Initialize database
  useEffect(() => {
    openDatabase()
      .then((db) => {
        dbRef.current = db;
      })
      .catch(console.error);

    return () => {
      dbRef.current?.close();
    };
  }, []);

  // Monitor online status
  useEffect(() => {
    const handleOnline = () => setIsOnline(true);
    const handleOffline = () => setIsOnline(false);

    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);

    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  // Count pending changes
  useEffect(() => {
    const countPending = async () => {
      if (!dbRef.current) return;

      const transaction = dbRef.current.transaction(STORE_SYNC_QUEUE, 'readonly');
      const store = transaction.objectStore(STORE_SYNC_QUEUE);
      const count = await new Promise<number>((resolve, reject) => {
        const request = store.count();
        request.onsuccess = () => resolve(request.result);
        request.onerror = () => reject(request.error);
      });

      setPendingChanges(count);
    };

    countPending();
    const interval = setInterval(countPending, 5000);
    return () => clearInterval(interval);
  }, []);

  /**
   * Save item to local IndexedDB
   */
  const saveLocal = useCallback(
    async (item: T): Promise<void> => {
      if (!dbRef.current) {
        await openDatabase().then((db) => {
          dbRef.current = db;
        });
      }

      const db = dbRef.current!;
      const transaction = db.transaction([storeName, STORE_SYNC_QUEUE], 'readwrite');

      // Save to main store
      const mainStore = transaction.objectStore(storeName);
      await new Promise<void>((resolve, reject) => {
        const request = mainStore.put(item);
        request.onsuccess = () => resolve();
        request.onerror = () => reject(request.error);
      });

      // Add to sync queue if offline
      if (!navigator.onLine) {
        const syncStore = transaction.objectStore(STORE_SYNC_QUEUE);
        const queueItem: SyncQueueItem = {
          id: `sync-${item.id}-${Date.now()}`,
          type: 'update',
          data: item as unknown as SavedBook,
          timestamp: Date.now(),
          retries: 0,
        };
        await new Promise<void>((resolve, reject) => {
          const request = syncStore.put(queueItem);
          request.onsuccess = () => resolve();
          request.onerror = () => reject(request.error);
        });
      }
    },
    [storeName]
  );

  /**
   * Get item from local IndexedDB
   */
  const getLocal = useCallback(
    async (id: string): Promise<T | undefined> => {
      if (!dbRef.current) {
        await openDatabase().then((db) => {
          dbRef.current = db;
        });
      }

      const db = dbRef.current!;
      const transaction = db.transaction(storeName, 'readonly');
      const store = transaction.objectStore(storeName);

      return new Promise((resolve, reject) => {
        const request = store.get(id);
        request.onsuccess = () => resolve(request.result);
        request.onerror = () => reject(request.error);
      });
    },
    [storeName]
  );

  /**
   * Get all items from local IndexedDB
   */
  const getAllLocal = useCallback(async (): Promise<T[]> => {
    if (!dbRef.current) {
      await openDatabase().then((db) => {
        dbRef.current = db;
      });
    }

    const db = dbRef.current!;
    const transaction = db.transaction(storeName, 'readonly');
    const store = transaction.objectStore(storeName);

    return new Promise((resolve, reject) => {
      const request = store.getAll();
      request.onsuccess = () => resolve(request.result);
      request.onerror = () => reject(request.error);
    });
  }, [storeName]);

  /**
   * Delete item from local IndexedDB
   */
  const deleteLocal = useCallback(
    async (id: string): Promise<void> => {
      if (!dbRef.current) {
        await openDatabase().then((db) => {
          dbRef.current = db;
        });
      }

      const db = dbRef.current!;
      const transaction = db.transaction([storeName, STORE_SYNC_QUEUE], 'readwrite');

      const mainStore = transaction.objectStore(storeName);
      await new Promise<void>((resolve, reject) => {
        const request = mainStore.delete(id);
        request.onsuccess = () => resolve();
        request.onerror = () => reject(request.error);
      });

      // Add to sync queue if offline
      if (!navigator.onLine) {
        const syncStore = transaction.objectStore(STORE_SYNC_QUEUE);
        const queueItem: SyncQueueItem = {
          id: `sync-delete-${id}-${Date.now()}`,
          type: 'delete',
          data: id,
          timestamp: Date.now(),
          retries: 0,
        };
        await new Promise<void>((resolve, reject) => {
          const request = syncStore.put(queueItem);
          request.onsuccess = () => resolve();
          request.onerror = () => reject(request.error);
        });
      }
    },
    [storeName]
  );

  /**
   * Sync pending changes with server
   */
  const syncWithServer = useCallback(async (): Promise<void> => {
    if (!navigator.onLine || !onlineSync || !dbRef.current) return;

    setIsSyncing(true);

    try {
      const db = dbRef.current;
      const transaction = db.transaction(STORE_SYNC_QUEUE, 'readonly');
      const store = transaction.objectStore(STORE_SYNC_QUEUE);

      const items = await new Promise<SyncQueueItem[]>((resolve, reject) => {
        const request = store.getAll();
        request.onsuccess = () => resolve(request.result);
        request.onerror = () => reject(request.error);
      });

      if (items.length === 0) {
        setLastSyncTime(new Date());
        return;
      }

      // Group by type and sync
      const updates = items.filter((i) => i.type === 'update').map((i) => i.data as unknown as T);

      if (updates.length > 0) {
        await onlineSync(updates);
      }

      // Clear synced items from queue
      const clearTransaction = db.transaction(STORE_SYNC_QUEUE, 'readwrite');
      const clearStore = clearTransaction.objectStore(STORE_SYNC_QUEUE);

      for (const item of items) {
        await new Promise<void>((resolve, reject) => {
          const request = clearStore.delete(item.id);
          request.onsuccess = () => resolve();
          request.onerror = () => reject(request.error);
        });
      }

      setLastSyncTime(new Date());
      setPendingChanges(0);
    } catch (error) {
      console.error('Sync failed:', error);
    } finally {
      setIsSyncing(false);
    }
  }, [onlineSync]);

  // Auto-sync when coming online
  useEffect(() => {
    if (isOnline && pendingChanges > 0) {
      syncWithServer();
    }
  }, [isOnline, pendingChanges, syncWithServer]);

  return {
    isOnline,
    isSyncing,
    pendingChanges,
    lastSyncTime,
    saveLocal,
    getLocal,
    getAllLocal,
    deleteLocal,
    syncWithServer,
  };
}

/**
 * Hook specifically for offline book management
 */
export function useOfflineBooks() {
  return useOfflineFirst<SavedBook>(STORE_BOOKS);
}

export default useOfflineFirst;

import { type TouchEvent, useCallback, useRef, useState } from 'react';

export type SwipeDirection = 'left' | 'right' | 'up' | 'down';

interface SwipeConfig {
  threshold?: number; // minimum distance to trigger swipe
  velocity?: number; // minimum velocity to trigger swipe
  onSwipeLeft?: () => void;
  onSwipeRight?: () => void;
  onSwipeUp?: () => void;
  onSwipeDown?: () => void;
  onSwipe?: (direction: SwipeDirection) => void;
  preventDefaultOnSwipe?: boolean;
}

interface SwipeState {
  swiping: boolean;
  direction: SwipeDirection | null;
  offset: { x: number; y: number };
  velocity: { x: number; y: number };
}

interface TouchPoint {
  x: number;
  y: number;
  time: number;
}

export function useSwipeGesture(config: SwipeConfig = {}) {
  const {
    threshold = 50,
    velocity: velocityThreshold = 0.3,
    onSwipeLeft,
    onSwipeRight,
    onSwipeUp,
    onSwipeDown,
    onSwipe,
    preventDefaultOnSwipe = false,
  } = config;

  const [state, setState] = useState<SwipeState>({
    swiping: false,
    direction: null,
    offset: { x: 0, y: 0 },
    velocity: { x: 0, y: 0 },
  });

  const startRef = useRef<TouchPoint | null>(null);
  const currentRef = useRef<TouchPoint | null>(null);

  const handleTouchStart = useCallback((e: TouchEvent) => {
    const touch = e.touches[0];
    startRef.current = {
      x: touch.clientX,
      y: touch.clientY,
      time: Date.now(),
    };
    currentRef.current = startRef.current;
    setState((prev) => ({ ...prev, swiping: true }));
  }, []);

  const handleTouchMove = useCallback(
    (e: TouchEvent) => {
      if (!startRef.current) return;

      const touch = e.touches[0];
      const now = Date.now();

      currentRef.current = {
        x: touch.clientX,
        y: touch.clientY,
        time: now,
      };

      const deltaX = currentRef.current.x - startRef.current.x;
      const deltaY = currentRef.current.y - startRef.current.y;
      const deltaTime = (now - startRef.current.time) / 1000;

      const velocityX = deltaX / deltaTime;
      const velocityY = deltaY / deltaTime;

      // Determine swipe direction
      let direction: SwipeDirection | null = null;
      if (Math.abs(deltaX) > Math.abs(deltaY)) {
        direction = deltaX > 0 ? 'right' : 'left';
      } else {
        direction = deltaY > 0 ? 'down' : 'up';
      }

      setState({
        swiping: true,
        direction,
        offset: { x: deltaX, y: deltaY },
        velocity: { x: velocityX, y: velocityY },
      });

      if (preventDefaultOnSwipe && Math.abs(deltaX) > 10) {
        e.preventDefault();
      }
    },
    [preventDefaultOnSwipe]
  );

  const handleTouchEnd = useCallback(() => {
    if (!startRef.current || !currentRef.current) {
      setState({
        swiping: false,
        direction: null,
        offset: { x: 0, y: 0 },
        velocity: { x: 0, y: 0 },
      });
      return;
    }

    const deltaX = currentRef.current.x - startRef.current.x;
    const deltaY = currentRef.current.y - startRef.current.y;
    const deltaTime = (currentRef.current.time - startRef.current.time) / 1000;

    const velocityX = Math.abs(deltaX / deltaTime);
    const velocityY = Math.abs(deltaY / deltaTime);

    const absX = Math.abs(deltaX);
    const absY = Math.abs(deltaY);

    let direction: SwipeDirection | null = null;

    // Check if swipe meets threshold (distance or velocity)
    if (absX > absY) {
      if (absX > threshold || velocityX > velocityThreshold * 1000) {
        direction = deltaX > 0 ? 'right' : 'left';
      }
    } else if (absY > threshold || velocityY > velocityThreshold * 1000) {
      direction = deltaY > 0 ? 'down' : 'up';
    }

    // Trigger callbacks
    if (direction) {
      onSwipe?.(direction);

      switch (direction) {
        case 'left':
          onSwipeLeft?.();
          break;
        case 'right':
          onSwipeRight?.();
          break;
        case 'up':
          onSwipeUp?.();
          break;
        case 'down':
          onSwipeDown?.();
          break;
      }
    }

    // Reset state
    startRef.current = null;
    currentRef.current = null;
    setState({ swiping: false, direction: null, offset: { x: 0, y: 0 }, velocity: { x: 0, y: 0 } });
  }, [threshold, velocityThreshold, onSwipe, onSwipeLeft, onSwipeRight, onSwipeUp, onSwipeDown]);

  const handlers = {
    onTouchStart: handleTouchStart,
    onTouchMove: handleTouchMove,
    onTouchEnd: handleTouchEnd,
    onTouchCancel: handleTouchEnd,
  };

  return { ...state, handlers };
}

import { AnimatePresence, type PanInfo, motion } from 'framer-motion';
// Swipeable Page Navigator Component
import type React from 'react';
import { Button } from '../components/ui/button';

interface SwipeablePageProps {
  currentPage: number;
  totalPages: number;
  onPageChange: (page: number) => void;
  children: React.ReactNode;
  className?: string;
}

export const SwipeablePage: React.FC<SwipeablePageProps> = ({
  currentPage,
  totalPages,
  onPageChange,
  children,
  className = '',
}) => {
  const handleDragEnd = (_event: any, info: PanInfo) => {
    const threshold = 100;
    const velocity = info.velocity.x;
    const offset = info.offset.x;

    if (offset < -threshold || velocity < -500) {
      // Swiped left - next page
      if (currentPage < totalPages - 1) {
        onPageChange(currentPage + 1);
      }
    } else if (offset > threshold || velocity > 500) {
      // Swiped right - previous page
      if (currentPage > 0) {
        onPageChange(currentPage - 1);
      }
    }
  };

  return (
    <motion.div
      className={`touch-pan-y ${className}`}
      drag="x"
      dragConstraints={{ left: 0, right: 0 }}
      dragElastic={0.2}
      onDragEnd={handleDragEnd}
      whileDrag={{ cursor: 'grabbing' }}
    >
      <AnimatePresence mode="wait">
        <motion.div
          key={currentPage}
          initial={{ opacity: 0, x: 50 }}
          animate={{ opacity: 1, x: 0 }}
          exit={{ opacity: 0, x: -50 }}
          transition={{ duration: 0.2 }}
        >
          {children}
        </motion.div>
      </AnimatePresence>
    </motion.div>
  );
};

// Swipe indicator dots
interface SwipeDotsProps {
  total: number;
  current: number;
  onDotClick?: (index: number) => void;
  className?: string;
}

export const SwipeDots: React.FC<SwipeDotsProps> = ({
  total,
  current,
  onDotClick,
  className = '',
}) => {
  return (
    <div className={`flex items-center justify-center gap-2 ${className}`}>
      {Array.from({ length: total }).map((_, i) => (
        <Button
          variant="ghost"
          key={i}
          onClick={() => onDotClick?.(i)}
          className={`
                        w-2 h-2 rounded-full
                        ${
                          i === current
                            ? 'w-6 bg-coral-burst'
                            : 'bg-gray-300 dark:bg-gray-600 hover:bg-gray-400'
                        }
                    `}
          aria-label={`Go to page ${i + 1}`}
        />
      ))}
    </div>
  );
};

// Pull to refresh hook
interface PullToRefreshConfig {
  onRefresh: () => Promise<void>;
  threshold?: number;
}

export function usePullToRefresh({ onRefresh, threshold = 80 }: PullToRefreshConfig) {
  const [pulling, setPulling] = useState(false);
  const [pullDistance, setPullDistance] = useState(0);
  const [refreshing, setRefreshing] = useState(false);

  const startY = useRef(0);
  const containerRef = useRef<HTMLDivElement>(null);

  const handleTouchStart = useCallback((e: TouchEvent) => {
    if (containerRef.current?.scrollTop === 0) {
      startY.current = e.touches[0].clientY;
      setPulling(true);
    }
  }, []);

  const handleTouchMove = useCallback(
    (e: TouchEvent) => {
      if (!pulling || refreshing) return;

      const currentY = e.touches[0].clientY;
      const distance = Math.max(0, currentY - startY.current);

      // Apply resistance
      const resistedDistance = Math.min(distance * 0.5, threshold * 1.5);
      setPullDistance(resistedDistance);

      if (resistedDistance > 10) {
        e.preventDefault();
      }
    },
    [pulling, refreshing, threshold]
  );

  const handleTouchEnd = useCallback(async () => {
    if (pullDistance >= threshold && !refreshing) {
      setRefreshing(true);
      await onRefresh();
      setRefreshing(false);
    }

    setPulling(false);
    setPullDistance(0);
  }, [pullDistance, threshold, refreshing, onRefresh]);

  const progress = Math.min(pullDistance / threshold, 1);
  const shouldRefresh = pullDistance >= threshold;

  return {
    containerRef,
    pullDistance,
    refreshing,
    progress,
    shouldRefresh,
    handlers: {
      onTouchStart: handleTouchStart as unknown as React.TouchEventHandler,
      onTouchMove: handleTouchMove as unknown as React.TouchEventHandler,
      onTouchEnd: handleTouchEnd,
    },
  };
}

// Pull to refresh indicator component
interface PullIndicatorProps {
  distance: number;
  threshold: number;
  refreshing: boolean;
}

export const PullIndicator: React.FC<PullIndicatorProps> = ({
  distance,
  threshold,
  refreshing,
}) => {
  const progress = Math.min(distance / threshold, 1);

  if (distance === 0 && !refreshing) return null;

  return (
    <motion.div
      className="absolute top-0 left-0 right-0 flex items-center justify-center pointer-events-none z-50"
      style={{ height: distance }}
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
    >
      <motion.div
        className={`
                    w-10 h-10 rounded-full flex items-center justify-center
                    ${refreshing ? 'bg-coral-burst' : 'bg-gray-200 dark:bg-gray-700'}
                `}
        animate={refreshing ? { rotate: 360 } : { rotate: progress * 360 }}
        transition={
          refreshing ? { repeat: Number.POSITIVE_INFINITY, duration: 1, ease: 'linear' } : {}
        }
      >
        <svg
          className={`w-5 h-5 ${refreshing ? 'text-white' : 'text-gray-500'}`}
          fill="none"
          viewBox="0 0 24 24"
          stroke="currentColor"
        >
          <path
            strokeLinecap="round"
            strokeLinejoin="round"
            strokeWidth={2}
            d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15"
          />
        </svg>
      </motion.div>
    </motion.div>
  );
};

export default useSwipeGesture;

import { useCallback, useEffect, useRef, useState } from 'react';

interface HistoryState<T> {
  past: T[];
  present: T;
  future: T[];
}

interface UseUndoRedoOptions<T> {
  maxHistory?: number;
  onUndo?: (state: T) => void;
  onRedo?: (state: T) => void;
}

export function useUndoRedo<T>(initialState: T, options: UseUndoRedoOptions<T> = {}) {
  const { maxHistory = 50, onUndo, onRedo } = options;

  const [history, setHistory] = useState<HistoryState<T>>({
    past: [],
    present: initialState,
    future: [],
  });

  const canUndo = history.past.length > 0;
  const canRedo = history.future.length > 0;

  // Update state and push to history
  const set = useCallback(
    (newState: T | ((prev: T) => T)) => {
      setHistory((prev) => {
        const nextState =
          typeof newState === 'function' ? (newState as (prev: T) => T)(prev.present) : newState;

        // Don't add to history if state hasn't changed
        if (JSON.stringify(nextState) === JSON.stringify(prev.present)) {
          return prev;
        }

        const newPast = [...prev.past, prev.present].slice(-maxHistory);

        return {
          past: newPast,
          present: nextState,
          future: [], // Clear redo stack on new change
        };
      });
    },
    [maxHistory]
  );

  // Undo to previous state
  const undo = useCallback(() => {
    setHistory((prev) => {
      if (prev.past.length === 0) return prev;

      const previous = prev.past[prev.past.length - 1];
      const newPast = prev.past.slice(0, -1);

      onUndo?.(previous);

      return {
        past: newPast,
        present: previous,
        future: [prev.present, ...prev.future],
      };
    });
  }, [onUndo]);

  // Redo to next state
  const redo = useCallback(() => {
    setHistory((prev) => {
      if (prev.future.length === 0) return prev;

      const next = prev.future[0];
      const newFuture = prev.future.slice(1);

      onRedo?.(next);

      return {
        past: [...prev.past, prev.present],
        present: next,
        future: newFuture,
      };
    });
  }, [onRedo]);

  // Reset history
  const reset = useCallback((newState: T) => {
    setHistory({
      past: [],
      present: newState,
      future: [],
    });
  }, []);

  // Clear history but keep current state
  const clearHistory = useCallback(() => {
    setHistory((prev) => ({
      past: [],
      present: prev.present,
      future: [],
    }));
  }, []);

  // Keyboard shortcuts
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if ((e.metaKey || e.ctrlKey) && e.key === 'z') {
        if (e.shiftKey) {
          e.preventDefault();
          redo();
        } else {
          e.preventDefault();
          undo();
        }
      }
      if ((e.metaKey || e.ctrlKey) && e.key === 'y') {
        e.preventDefault();
        redo();
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [undo, redo]);

  return {
    state: history.present,
    set,
    undo,
    redo,
    reset,
    clearHistory,
    canUndo,
    canRedo,
    historyLength: history.past.length,
    futureLength: history.future.length,
  };
}

// Hook for auto-saving
interface UseAutoSaveOptions<T> {
  data: T;
  onSave: (data: T) => Promise<void> | void;
  interval?: number; // milliseconds
  enabled?: boolean;
  debounceDelay?: number;
}

export function useAutoSave<T>({
  data,
  onSave,
  interval = 30000, // 30 seconds default
  enabled = true,
  debounceDelay = 2000,
}: UseAutoSaveOptions<T>) {
  const [isSaving, setIsSaving] = useState(false);
  const [lastSaved, setLastSaved] = useState<Date | null>(null);
  const [error, setError] = useState<string | null>(null);
  const lastDataRef = useRef<string>(JSON.stringify(data));
  const timeoutRef = useRef<NodeJS.Timeout | null>(null);
  const intervalRef = useRef<NodeJS.Timeout | null>(null);

  // Save function
  const save = useCallback(
    async (force = false) => {
      const currentData = JSON.stringify(data);

      // Skip if data hasn't changed (unless forced)
      if (!force && currentData === lastDataRef.current) {
        return;
      }

      setIsSaving(true);
      setError(null);

      try {
        await onSave(data);
        lastDataRef.current = currentData;
        setLastSaved(new Date());
      } catch (err) {
        setError(err instanceof Error ? err.message : 'Failed to save');
        console.error('[AutoSave] Error:', err);
      } finally {
        setIsSaving(false);
      }
    },
    [data, onSave]
  );

  // Debounced save on data change
  useEffect(() => {
    if (!enabled) return;

    if (timeoutRef.current) {
      clearTimeout(timeoutRef.current);
    }

    timeoutRef.current = setTimeout(() => {
      save();
    }, debounceDelay);

    return () => {
      if (timeoutRef.current) {
        clearTimeout(timeoutRef.current);
      }
    };
  }, [data, enabled, debounceDelay, save]);

  // Periodic save
  useEffect(() => {
    if (!enabled || interval <= 0) return;

    intervalRef.current = setInterval(() => {
      save();
    }, interval);

    return () => {
      if (intervalRef.current) {
        clearInterval(intervalRef.current);
      }
    };
  }, [enabled, interval, save]);

  // Save on unmount
  useEffect(() => {
    return () => {
      if (enabled) {
        save(true);
      }
    };
  }, []);

  // Keyboard shortcut for manual save
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if ((e.metaKey || e.ctrlKey) && e.key === 's') {
        e.preventDefault();
        save(true);
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [save]);

  return {
    isSaving,
    lastSaved,
    error,
    save: () => save(true),
  };
}

import { Check, Cloud, CloudOff, Loader2 } from 'lucide-react';
// Auto-save indicator component
import type React from 'react';

interface AutoSaveIndicatorProps {
  isSaving: boolean;
  lastSaved: Date | null;
  error: string | null;
}

export const AutoSaveIndicator: React.FC<AutoSaveIndicatorProps> = ({
  isSaving,
  lastSaved,
  error,
}) => {
  const formatTime = (date: Date) => {
    const now = new Date();
    const diff = now.getTime() - date.getTime();

    if (diff < 60000) return 'Just now';
    if (diff < 3600000) return `${Math.floor(diff / 60000)}m ago`;
    return date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
  };

  if (error) {
    return (
      <div className="flex items-center gap-2 text-red-500 text-sm">
        <CloudOff className="w-4 h-4" />
        <span>Failed to save</span>
      </div>
    );
  }

  if (isSaving) {
    return (
      <div className="flex items-center gap-2 text-gray-500 dark:text-gray-400 text-sm">
        <Loader2 className="w-4 h-4 animate-spin" />
        <span>Saving...</span>
      </div>
    );
  }

  if (lastSaved) {
    return (
      <div className="flex items-center gap-2 text-green-600 dark:text-green-400 text-sm">
        <Check className="w-4 h-4" />
        <span>Saved {formatTime(lastSaved)}</span>
      </div>
    );
  }

  return (
    <div className="flex items-center gap-2 text-gray-400 text-sm">
      <Cloud className="w-4 h-4" />
      <span>Auto-save enabled</span>
    </div>
  );
};

export default { useUndoRedo, useAutoSave, AutoSaveIndicator };

import { useEffect, useState } from 'react';
import { useAuth } from '../contexts/AuthContext';

export interface UserSettings {
  displayName: string;
  email: string;
  bio: string;
  defaultStyle: string;
  temperature: number;
  emailUpdates: boolean;
  marketingEmails: boolean;
  publicProfile: boolean;
  dataSharing: boolean;
}

export interface UserDisplayData {
  displayName: string;
  email: string;
  avatarUrl: string | null;
  bio: string;
  settings: UserSettings;
}

const DEFAULT_SETTINGS: UserSettings = {
  displayName: '',
  email: '',
  bio: 'I love creating magical stories for children...',
  defaultStyle: 'Watercolor',
  temperature: 0.7,
  emailUpdates: true,
  marketingEmails: false,
  publicProfile: true,
  dataSharing: false,
};

/**
 * Hook to get unified user display data from Auth context (DB profile), localStorage, and user metadata.
 * Priority chain: DB profile ΓåÆ localStorage ΓåÆ user_metadata ΓåÆ fallback
 */
export const useUserSettings = (): UserDisplayData & {
  updateSettings: (settings: Partial<UserSettings>) => void;
} => {
  const { user, userProfile } = useAuth();

  const [settings, setSettings] = useState<UserSettings>(() => {
    try {
      const saved = localStorage.getItem('genesis_settings');
      return saved ? { ...DEFAULT_SETTINGS, ...JSON.parse(saved) } : DEFAULT_SETTINGS;
    } catch {
      return DEFAULT_SETTINGS;
    }
  });

  const [customAvatar, setCustomAvatar] = useState<string | null>(() => {
    try {
      return localStorage.getItem('genesis_avatar');
    } catch {
      return null;
    }
  });

  // Listen for storage changes (for cross-tab sync)
  useEffect(() => {
    const handleStorageChange = (e: StorageEvent) => {
      if (e.key === 'genesis_settings' && e.newValue) {
        try {
          setSettings({ ...DEFAULT_SETTINGS, ...JSON.parse(e.newValue) });
        } catch {}
      }
      if (e.key === 'genesis_avatar') {
        setCustomAvatar(e.newValue);
      }
    };

    window.addEventListener('storage', handleStorageChange);
    return () => window.removeEventListener('storage', handleStorageChange);
  }, []);

  // Sync with user data when user or DB profile changes
  // DB profile (via AuthContext) is the source of truth for identity fields
  useEffect(() => {
    if (user) {
      const userName =
        userProfile?.display_name ||
        user.user_metadata?.full_name ||
        user.user_metadata?.name ||
        user.email?.split('@')[0] ||
        'Creative Author';

      setSettings((prev) => ({
        ...prev,
        // Force-set identity from DB ΓÇö don't use || which preserves stale localStorage
        displayName: userName,
        email: userProfile?.email || user.email || prev.email,
      }));
    }
  }, [user, userProfile]);

  const updateSettings = (newSettings: Partial<UserSettings>) => {
    setSettings((prev) => {
      const updated = { ...prev, ...newSettings };
      try {
        localStorage.setItem('genesis_settings', JSON.stringify(updated));
      } catch (e) {
        console.error('Failed to save settings:', e);
      }
      return updated;
    });
  };

  // Determine best avatar to use: custom upload > DB profile > user metadata > null
  const avatarUrl =
    customAvatar ||
    userProfile?.avatar_url ||
    user?.user_metadata?.avatar_url ||
    user?.user_metadata?.picture ||
    null;

  // Determine best display name: localStorage settings > DB profile > user metadata > email prefix
  const displayName =
    settings.displayName ||
    userProfile?.display_name ||
    user?.user_metadata?.full_name ||
    user?.user_metadata?.name ||
    user?.email?.split('@')[0] ||
    'Creator';

  return {
    displayName,
    email: settings.email || user?.email || '',
    avatarUrl,
    bio: settings.bio,
    settings,
    updateSettings,
  };
};

/**
 * Get the user's preferred default art style from settings
 */
export const getDefaultArtStyle = (): string => {
  try {
    const saved = localStorage.getItem('genesis_settings');
    if (saved) {
      const settings = JSON.parse(saved);
      return settings.defaultStyle || 'Watercolor';
    }
  } catch {}
  return 'Watercolor';
};

/**
