  } catch {}
  return 0.7;
};

/**
 * i18n Configuration for Genesis
 *
 * Uses react-i18next with lazy loading, browser detection,
 * and namespace support for organized translations.
 */

import i18n from 'i18next';
import LanguageDetector from 'i18next-browser-languagedetector';
import HttpBackend from 'i18next-http-backend';
import { initReactI18next } from 'react-i18next';

import { FALLBACK_LANGUAGE, LANGUAGE_STORAGE_KEY, TRANSLATION_NAMESPACES } from './languages';

// Initialize i18next with error handling
const initPromise = i18n
  // Load translations from /public/locales
  .use(HttpBackend)
  // Detect user language from localStorage or browser
  .use(LanguageDetector)
  // Connect to React
  .use(initReactI18next)
  .init({
    // Default/fallback language
    fallbackLng: FALLBACK_LANGUAGE,

    // Supported languages (for validation)
    supportedLngs: ['en', 'es', 'fr', 'de', 'zh-CN', 'ar', 'pt', 'hi', 'ja'],

    // Debug mode (disable in production)
    debug: import.meta.env.DEV,

    // Language detection configuration
    detection: {
      // Order of detection methods
      order: ['localStorage', 'navigator', 'htmlTag'],
      // Cache the detected language
      caches: ['localStorage'],
      // Key for localStorage
      lookupLocalStorage: LANGUAGE_STORAGE_KEY,
    },

    // Backend configuration for loading translation files
    backend: {
      // Path to translation files
      loadPath: '/locales/{{lng}}/{{ns}}.json',
      // Request options
      requestOptions: {
        cache: 'default',
      },
    },

    // Available namespaces
    ns: TRANSLATION_NAMESPACES,

    // Default namespace
    defaultNS: 'common',

    // Preload only the essential namespaces
    preload: ['en'],

    // Load namespaces on demand
    partialBundledLanguages: true,

    // Interpolation settings
    interpolation: {
      // React already escapes values
      escapeValue: false,
      // Format function for dates, numbers, etc.
      format: (value, format, lng) => {
        if (format === 'uppercase') return value.toUpperCase();
        if (format === 'lowercase') return value.toLowerCase();
        if (format === 'capitalize') {
          return value.charAt(0).toUpperCase() + value.slice(1);
        }
        if (value instanceof Date) {
          return new Intl.DateTimeFormat(lng).format(value);
        }
        if (typeof value === 'number') {
          return new Intl.NumberFormat(lng).format(value);
        }
        return value;
      },
    },

    // React-specific options
    react: {
      // Don't use Suspense - handle loading states manually
      useSuspense: false,
      // Bind i18n to React
      bindI18n: 'languageChanged loaded',
      // Bind store
      bindI18nStore: 'added removed',
      // Translating of children default
      transEmptyNodeValue: '',
      // Key for trans component
      transSupportBasicHtmlNodes: true,
      // Allowed HTML nodes in Trans component
      transKeepBasicHtmlNodesFor: ['br', 'strong', 'i', 'em', 'b', 'u', 'span'],
    },

    // Return objects/arrays (not just strings)
    returnObjects: true,

    // Return empty string for missing keys (in development)
    returnEmptyString: false,

    // Return key if translation is missing
    returnNull: false,

    // Key separator for nested translations
    keySeparator: '.',

    // Namespace separator
    nsSeparator: ':',

    // Pluralization
    pluralSeparator: '_',

    // Context separator
    contextSeparator: '_',

    // Load language on init
    load: 'currentOnly',

    // Clean code from language (e.g., 'en-US' -> 'en')
    cleanCode: true,

    // Non-explicit supported languages fallback to 'en'
    nonExplicitSupportedLngs: false,

    // Save missing translations (for development)
    saveMissing: import.meta.env.DEV,

    // Missing key handler (for development)
    missingKeyHandler: (lngs, ns, key, fallbackValue) => {
      if (import.meta.env.DEV) {
        console.warn(`[i18n] Missing translation: ${ns}:${key} for languages: ${lngs.join(', ')}`);
      }
    },
  })
  .catch((err) => {
    console.error('[i18n] Initialization failed:', err);
  });

// Export the initialization promise for components that need to wait
export const i18nReady = initPromise;

// Export the i18n instance
export default i18n;

/**
 * Change the current language
 */
export const changeLanguage = async (languageCode: string): Promise<void> => {
  await i18n.changeLanguage(languageCode);
};

/**
 * Get the current language code
 */
export const getCurrentLanguage = (): string => {
  return i18n.language || FALLBACK_LANGUAGE;
};

/**
 * Check if a language is loaded
 */
export const isLanguageLoaded = (languageCode: string): boolean => {
  return i18n.hasResourceBundle(languageCode, 'common');
};

/**
 * Load a specific namespace for a language
 */
export const loadNamespace = async (namespace: string): Promise<void> => {
  await i18n.loadNamespaces(namespace);
};

/**
 * Add custom translations at runtime
 */
export const addTranslations = (
  languageCode: string,
  namespace: string,
  translations: Record<string, any>
): void => {
  i18n.addResourceBundle(languageCode, namespace, translations, true, true);
};

import type React from 'react';
import { type ReactNode, createContext, useEffect, useState } from 'react';
import { fontPairings } from '../config/fontPairings';
import { useDynamicFontLoader } from '../hooks/useDynamicFontLoader';
import type { FontPairing } from '../types/fonts';

interface FontContextType {
  activeFontPairing: FontPairing;
  setFontPairing: (pairingId: string) => void;
  availablePairings: FontPairing[];
  isLoading: boolean;
}

export const FontContext = createContext<FontContextType | undefined>(undefined);

// Default fallback font pairing in case import fails
const DEFAULT_FONT_PAIRING: FontPairing = {
  id: 'default',
  name: 'Default',
  description: 'System default fonts',
  category: 'playful',
  headingFont: { family: 'system-ui', weights: [400, 700], fallback: 'sans-serif' },
  bodyFont: { family: 'system-ui', weights: [400, 700], fallback: 'sans-serif' },
  preview: { headingText: 'Preview', bodyText: 'Preview text' },
  bestFor: ['General'],
};

export const FontProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  // Initialize from localStorage or default with defensive fallback
  const [activeFontPairing, setActiveFontPairingState] = useState<FontPairing>(() => {
    try {
      if (!fontPairings || fontPairings.length === 0) {
        console.warn('[FontContext] No font pairings available, using default');
        return DEFAULT_FONT_PAIRING;
      }
      const savedId = localStorage.getItem('genesis_font_pairing');
      return fontPairings.find((p) => p.id === savedId) || fontPairings[0] || DEFAULT_FONT_PAIRING;
    } catch (error) {
      console.error('[FontContext] Error initializing font pairing:', error);
      return DEFAULT_FONT_PAIRING;
    }
  });

  // Use the dynamic loader hook
  const { isLoading } = useDynamicFontLoader(activeFontPairing);

  const setFontPairing = (pairingId: string) => {
    const pairing = fontPairings.find((p) => p.id === pairingId);
    if (pairing) {
      setActiveFontPairingState(pairing);
      localStorage.setItem('genesis_font_pairing', pairingId);
    }
  };

  // Apply CSS variables whenever the active font changes
  useEffect(() => {
    const root = document.documentElement;

    // Set font families
    root.style.setProperty(
      '--font-heading',
      `'${activeFontPairing.headingFont.family}', ${activeFontPairing.headingFont.fallback}`
    );
    root.style.setProperty(
      '--font-body',
      `'${activeFontPairing.bodyFont.family}', ${activeFontPairing.bodyFont.fallback}`
    );

    // Optional: Set font weights if needed for specific overrides,
    // but usually handled by utility classes
  }, [activeFontPairing]);

  return (
    <FontContext.Provider
      value={{
        activeFontPairing,
        setFontPairing,
        availablePairings: fontPairings,
        isLoading,
      }}
    >
      {children}
    </FontContext.Provider>
  );
};

/**
 * Language Context for Genesis
 *
 * Provides language management, RTL support, and formatting utilities
 * throughout the application.
 */

import type React from 'react';
import { createContext, useCallback, useContext, useEffect, useMemo, useState } from 'react';
import { useTranslation } from 'react-i18next';
import {
  FALLBACK_LANGUAGE,
  LANGUAGE_STORAGE_KEY,
  SUPPORTED_LANGUAGES,
  getDefaultLanguage,
  getLanguageByCode,
  isValidLanguageCode,
} from '../config/languages';
import type { Language, LanguageCode, LanguageContextType } from '../types/language.d';

// Create the context
const LanguageContext = createContext<LanguageContextType | undefined>(undefined);

interface LanguageProviderProps {
  children: React.ReactNode;
}

export const LanguageProvider: React.FC<LanguageProviderProps> = ({ children }) => {
  const { i18n } = useTranslation();
  const [isLoading, setIsLoading] = useState(false);
  const [currentLanguage, setCurrentLanguage] = useState<Language>(getDefaultLanguage());

  // Initialize language from i18n
  useEffect(() => {
    const currentCode = i18n.language as LanguageCode;
    if (isValidLanguageCode(currentCode)) {
      const lang = getLanguageByCode(currentCode);
      if (lang) {
        setCurrentLanguage(lang);
        applyLanguageToDocument(lang);
      }
    }
  }, [i18n.language]);

  // Listen for language changes from i18n
  useEffect(() => {
    const handleLanguageChange = (lng: string) => {
      if (isValidLanguageCode(lng)) {
        const lang = getLanguageByCode(lng as LanguageCode);
        if (lang) {
          setCurrentLanguage(lang);
          applyLanguageToDocument(lang);
        }
      }
    };

    i18n.on('languageChanged', handleLanguageChange);
    return () => {
      i18n.off('languageChanged', handleLanguageChange);
    };
  }, [i18n]);

  /**
   * Apply language settings to the document (RTL, lang attribute)
   */
  const applyLanguageToDocument = useCallback((language: Language) => {
    const html = document.documentElement;
    const body = document.body;

    // Set lang attribute
    html.setAttribute('lang', language.code);

    // Set direction attribute
    html.setAttribute('dir', language.direction);

    // Add RTL class for Tailwind utilities
    if (language.isRTL) {
      html.classList.add('rtl');
      html.classList.remove('ltr');
    } else {
      html.classList.add('ltr');
      html.classList.remove('rtl');
    }

    // Add language class to body for conditional styling
    body.className = body.className.replace(/lang-\w+/g, '');
    body.classList.add(`lang-${language.code}`);

    // Store preference
    localStorage.setItem(LANGUAGE_STORAGE_KEY, language.code);

    // Dispatch custom event to notify other components
    window.dispatchEvent(new CustomEvent('languageChanged', { detail: { language } }));
  }, []);

  /**
   * Change the current language
   */
  const changeLanguage = useCallback(
    async (code: LanguageCode): Promise<void> => {
      if (!isValidLanguageCode(code)) {
        console.error(`[LanguageContext] Invalid language code: ${code}`);
        return;
      }

      const targetLanguage = getLanguageByCode(code);
      if (!targetLanguage) {
        console.error(`[LanguageContext] Language not found: ${code}`);
        return;
      }

      setIsLoading(true);

      try {
        // Change i18n language (this loads the translation files)
        await i18n.changeLanguage(code);

        // Update state
        setCurrentLanguage(targetLanguage);

        // Apply to document
        applyLanguageToDocument(targetLanguage);

        console.warn(`[LanguageContext] Language changed to: ${targetLanguage.name}`);
      } catch (error) {
        console.error(`[LanguageContext] Failed to change language:`, error);
        // Fallback to English
        await i18n.changeLanguage(FALLBACK_LANGUAGE);
      } finally {
        setIsLoading(false);
      }
    },
    [i18n, applyLanguageToDocument]
  );

  /**
   * Format a date according to current locale
   */
  const formatDate = useCallback(
    (date: Date | string | number): string => {
      const dateObj = date instanceof Date ? date : new Date(date);
      try {
        return new Intl.DateTimeFormat(currentLanguage.numberFormat, {
          year: 'numeric',
          month: 'long',
          day: 'numeric',
        }).format(dateObj);
      } catch {
        return dateObj.toLocaleDateString();
      }
    },
    [currentLanguage.numberFormat]
  );

  /**
   * Format a number according to current locale
   */
  const formatNumber = useCallback(
    (num: number): string => {
      try {
        return new Intl.NumberFormat(currentLanguage.numberFormat).format(num);
      } catch {
        return num.toLocaleString();
      }
    },
    [currentLanguage.numberFormat]
  );

  /**
   * Format currency according to current locale
   */
  const formatCurrency = useCallback(
    (amount: number, currencyCode?: string): string => {
      const currency = currencyCode || currentLanguage.currency;
      try {
        return new Intl.NumberFormat(currentLanguage.numberFormat, {
          style: 'currency',
          currency,
        }).format(amount);
      } catch {
        return `${currency} ${amount.toFixed(2)}`;
      }
    },
    [currentLanguage.numberFormat, currentLanguage.currency]
  );

  /**
   * Format relative time (e.g., "2 hours ago")
   */
  const formatRelativeTime = useCallback(
    (date: Date | string | number): string => {
      const dateObj = date instanceof Date ? date : new Date(date);
      const now = new Date();
      const diffInSeconds = Math.floor((now.getTime() - dateObj.getTime()) / 1000);

      try {
        const rtf = new Intl.RelativeTimeFormat(currentLanguage.numberFormat, { numeric: 'auto' });

        if (diffInSeconds < 60) {
          return rtf.format(-diffInSeconds, 'second');
        } else if (diffInSeconds < 3600) {
          return rtf.format(-Math.floor(diffInSeconds / 60), 'minute');
        } else if (diffInSeconds < 86400) {
          return rtf.format(-Math.floor(diffInSeconds / 3600), 'hour');
        } else if (diffInSeconds < 2592000) {
          return rtf.format(-Math.floor(diffInSeconds / 86400), 'day');
        } else if (diffInSeconds < 31536000) {
          return rtf.format(-Math.floor(diffInSeconds / 2592000), 'month');
        } else {
          return rtf.format(-Math.floor(diffInSeconds / 31536000), 'year');
        }
      } catch {
        return dateObj.toLocaleDateString();
      }
    },
    [currentLanguage.numberFormat]
  );

  // Memoize context value
  const contextValue = useMemo<LanguageContextType>(
    () => ({
      currentLanguage,
      languages: SUPPORTED_LANGUAGES,
      changeLanguage,
      direction: currentLanguage.direction,
      isLoading,
      formatDate,
      formatNumber,
      formatCurrency,
      formatRelativeTime,
    }),
    [
      currentLanguage,
      changeLanguage,
      isLoading,
      formatDate,
      formatNumber,
      formatCurrency,
      formatRelativeTime,
    ]
  );

  return <LanguageContext.Provider value={contextValue}>{children}</LanguageContext.Provider>;
};

/**
 * Hook to access language context
 */
export const useLanguageContext = (): LanguageContextType => {
  const context = useContext(LanguageContext);
  if (context === undefined) {
    throw new Error('useLanguageContext must be used within a LanguageProvider');
  }
  return context;
};

export default LanguageContext;

/**
 * useDirection Hook
 *
 * Provides RTL/LTR direction utilities for components
 */

import { useMemo } from 'react';
import { useLanguageContext } from '../contexts/LanguageContext';
import type { TextDirection } from '../types/language.d';

interface UseDirectionReturn {
  /** Current text direction */
  direction: TextDirection;

  /** Whether the current direction is RTL */
  isRTL: boolean;

  /** Whether the current direction is LTR */
  isLTR: boolean;

  /** Get CSS logical property value based on direction */
  logical: {
    /** Returns 'right' for LTR, 'left' for RTL */
    start: 'left' | 'right';
    /** Returns 'left' for LTR, 'right' for RTL */
    end: 'right' | 'left';
    /** Returns 'ltr' or 'rtl' */
    dir: TextDirection;
  };

  /** Mirror a value for RTL (useful for icons) */
  mirror: <T>(ltrValue: T, rtlValue: T) => T;

  /** Get directional class names */
  getDirectionalClass: (ltrClass: string, rtlClass: string) => string;

  /** Flip horizontal alignment */
  flipAlign: (align: 'left' | 'right' | 'center') => 'left' | 'right' | 'center';

  /** Flip flex direction */
  flipFlexDirection: (direction: 'row' | 'row-reverse') => 'row' | 'row-reverse';
}

/**
 * Custom hook for RTL/LTR direction utilities
 */
export const useDirection = (): UseDirectionReturn => {
  const { direction, currentLanguage } = useLanguageContext();

  return useMemo(() => {
    const isRTL = direction === 'rtl';
    const isLTR = direction === 'ltr';

    return {
      direction,
      isRTL,
      isLTR,

      logical: {
        start: isRTL ? 'right' : 'left',
        end: isRTL ? 'left' : 'right',
        dir: direction,
      },

      mirror: <T>(ltrValue: T, rtlValue: T): T => {
        return isRTL ? rtlValue : ltrValue;
      },

      getDirectionalClass: (ltrClass: string, rtlClass: string): string => {
        return isRTL ? rtlClass : ltrClass;
      },

      flipAlign: (align: 'left' | 'right' | 'center'): 'left' | 'right' | 'center' => {
        if (align === 'center') return 'center';
        if (!isRTL) return align;
        return align === 'left' ? 'right' : 'left';
      },

      flipFlexDirection: (dir: 'row' | 'row-reverse'): 'row' | 'row-reverse' => {
        if (!isRTL) return dir;
        return dir === 'row' ? 'row-reverse' : 'row';
      },
    };
  }, [direction, currentLanguage]);
};

export default useDirection;

import { useEffect, useState } from 'react';
import type { FontPairing } from '../types/fonts';
import { loadFont, preconnectGoogleFonts } from '../utils/fontLoader';

export const useDynamicFontLoader = (activeFontPairing: FontPairing) => {
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    preconnectGoogleFonts();
  }, []);

  useEffect(() => {
    const loadFonts = async () => {
      setIsLoading(true);
      setError(null);

      // Add loading class to body for FOUT prevention
      document.body.classList.add('fonts-loading');

      try {
        await Promise.all([
          loadFont(activeFontPairing.headingFont),
          loadFont(activeFontPairing.bodyFont),
        ]);

        // Wait for fonts to be ready
        await document.fonts.ready;
      } catch (err) {
        console.error('Failed to load fonts:', err);
        setError('Failed to load selected fonts. Using system fallback.');
      } finally {
        document.body.classList.remove('fonts-loading');
        setIsLoading(false);
      }
    };

    loadFonts();
  }, [activeFontPairing.id]); // Only reload if ID changes

  return { isLoading, error };
};

/**
 * useLanguage Hook
 *
 * Provides easy access to language switching and translation utilities
 */

import { useCallback } from 'react';
import { useTranslation } from 'react-i18next';
import { getLanguageByCode, isValidLanguageCode } from '../config/languages';
import { useLanguageContext } from '../contexts/LanguageContext';
import type { Language, LanguageCode } from '../types/language.d';

interface UseLanguageReturn {
  /** Current active language */
  currentLanguage: Language;

  /** All available languages */
  languages: Language[];

  /** Current text direction */
  direction: 'ltr' | 'rtl';

  /** Whether language is currently loading */
  isLoading: boolean;

  /** Change to a specific language */
  changeLanguage: (code: LanguageCode) => Promise<void>;

  /** Translation function (from react-i18next) */
  t: (key: string, options?: Record<string, any>) => string;

  /** Check if current language is RTL */
  isRTL: boolean;

  /** Format date in current locale */
  formatDate: (date: Date | string | number) => string;

  /** Format number in current locale */
  formatNumber: (num: number) => string;

  /** Format currency in current locale */
  formatCurrency: (amount: number, currencyCode?: string) => string;

  /** Format relative time */
  formatRelativeTime: (date: Date | string | number) => string;

  /** Get language by code */
  getLanguage: (code: LanguageCode) => Language | undefined;

  /** Check if a language code is valid */
  isValidCode: (code: string) => boolean;
}

/**
 * Custom hook for language management
 */
export const useLanguage = (): UseLanguageReturn => {
  const { t } = useTranslation();
  const languageContext = useLanguageContext();

  const getLanguage = useCallback((code: LanguageCode): Language | undefined => {
    return getLanguageByCode(code);
  }, []);

  const isValidCode = useCallback((code: string): boolean => {
    return isValidLanguageCode(code);
  }, []);

  return {
    currentLanguage: languageContext.currentLanguage,
    languages: languageContext.languages,
    direction: languageContext.direction,
    isLoading: languageContext.isLoading,
    changeLanguage: languageContext.changeLanguage,
    t: t as (key: string, options?: Record<string, any>) => string,
    isRTL: languageContext.currentLanguage.isRTL,
    formatDate: languageContext.formatDate,
    formatNumber: languageContext.formatNumber,
    formatCurrency: languageContext.formatCurrency,
    formatRelativeTime: languageContext.formatRelativeTime,
    getLanguage,
    isValidCode,
  };
};

export default useLanguage;

