// ==============================================================================
// PRODUCTION-READY LOGGER UTILITY
// ==============================================================================
// Centralized logging that can be disabled in production
// ==============================================================================

const isDevelopment = import.meta.env.DEV;
const isDebugEnabled = import.meta.env.VITE_DEBUG === 'true';

type LogLevel = 'debug' | 'info' | 'warn' | 'error';

interface LoggerConfig {
  enabledLevels: LogLevel[];
  prefix: string;
}

const defaultConfig: LoggerConfig = {
  enabledLevels:
    isDevelopment || isDebugEnabled ? ['debug', 'info', 'warn', 'error'] : ['warn', 'error'],
  prefix: '[Genesis]',
};

class Logger {
  private config: LoggerConfig;

  constructor(config: Partial<LoggerConfig> = {}) {
    this.config = { ...defaultConfig, ...config };
  }

  private shouldLog(level: LogLevel): boolean {
    return this.config.enabledLevels.includes(level);
  }

  private formatMessage(level: LogLevel, message: string): string {
    const timestamp = new Date().toISOString();
    return `${this.config.prefix} [${timestamp}] [${level.toUpperCase()}] ${message}`;
  }

  debug(message: string, ...args: unknown[]): void {
    if (this.shouldLog('debug')) {
      console.warn(this.formatMessage('debug', message), ...args);
    }
  }

  info(message: string, ...args: unknown[]): void {
    if (this.shouldLog('info')) {
      console.info(this.formatMessage('info', message), ...args);
    }
  }

  warn(message: string, ...args: unknown[]): void {
    if (this.shouldLog('warn')) {
      console.warn(this.formatMessage('warn', message), ...args);
    }
  }

  error(message: string, ...args: unknown[]): void {
    if (this.shouldLog('error')) {
      console.error(this.formatMessage('error', message), ...args);
    }
  }

  // Create a child logger with a custom prefix
  child(prefix: string): Logger {
    return new Logger({
      ...this.config,
      prefix: `${this.config.prefix}:${prefix}`,
    });
  }
}

// Singleton instance
export const logger = new Logger();

// Named loggers for different modules
export const collaborationLogger = logger.child('Collab');
export const generationLogger = logger.child('Generate');
export const authLogger = logger.child('Auth');
export const storageLogger = logger.child('Storage');

export default logger;

export interface Particle {
  id: string;
  x: number;
  y: number;
  size: number;
  opacity: number;
  velocityX: number;
  velocityY: number;
  type: 'sparkle' | 'star' | 'bubble' | 'confetti';
  color?: string;
  rotation?: number;
  rotationSpeed?: number;
}

export const createParticle = (
  x: number,
  y: number,
  type: Particle['type'] = 'sparkle'
): Particle => {
  return {
    id: Math.random().toString(36).substring(7),
    x,
    y,
    size: type === 'sparkle' ? Math.random() * 3 + 1 : Math.random() * 5 + 4,
    opacity: Math.random() * 0.7 + 0.3,
    velocityX: (Math.random() - 0.5) * 2,
    velocityY: type === 'bubble' ? -(Math.random() * 2 + 1) : (Math.random() - 0.5) * 2,
    type,
    color: getParticleColor(type),
    rotation: Math.random() * 360,
    rotationSpeed: (Math.random() - 0.5) * 10,
  };
};

const getParticleColor = (type: Particle['type']): string => {
  switch (type) {
    case 'sparkle':
      return 'var(--color-accent-end)'; // gold-sunshine
    case 'star':
      return 'var(--color-primary-end)'; // coral-burst
    case 'bubble':
      return 'var(--color-text-light)'; // mint-breeze replacement
    case 'confetti':
      const colors = [
        'var(--color-accent-end)',
        'var(--color-primary-end)',
        'var(--color-text-light)',
        'var(--color-border)',
        'var(--color-accent-start)',
      ];
      return colors[Math.floor(Math.random() * colors.length)];
    default:
      return 'var(--color-accent-end)';
  }
};

export const updateParticle = (particle: Particle, deltaTime = 1): Particle => {
  return {
    ...particle,
    x: particle.x + particle.velocityX * deltaTime,
    y: particle.y + particle.velocityY * deltaTime,
    opacity: Math.max(0, particle.opacity - 0.01 * deltaTime),
    rotation: (particle.rotation || 0) + (particle.rotationSpeed || 0) * deltaTime,
  };
};

export const generateParticles = (
  count: number,
  centerX: number,
  centerY: number,
  radius = 100,
  type: Particle['type'] = 'sparkle'
): Particle[] => {
  const particles: Particle[] = [];
  for (let i = 0; i < count; i++) {
    const angle = Math.random() * 2 * Math.PI;
    const distance = Math.random() * radius;
    const x = centerX + Math.cos(angle) * distance;
    const y = centerY + Math.sin(angle) * distance;
    particles.push(createParticle(x, y, type));
  }
  return particles;
};
